#[test]
fn semantic_script_and_text_names_do_not_end_in_duplicate_ordinals() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let mut offenders = source
        .split(|character: char| !character.is_ascii_alphanumeric() && character != '_')
        .filter(|token| token.starts_with("EventScript_") || token.starts_with("gText_"))
        .filter(|token| {
            let Some(suffix) = token.rsplit('_').next() else {
                return false;
            };
            suffix.len() == 2
                && suffix.bytes().all(|byte| byte.is_ascii_digit())
                && !token.contains("_Question")
                && !token.contains("_Answer_")
        })
        .collect::<Vec<_>>();
    offenders.sort_unstable();
    offenders.dedup();
    assert!(
        offenders.is_empty(),
        "semantic symbols retain mechanical duplicate ordinals: {offenders:?}"
    );
}

#[test]
fn every_text_bearing_script_has_an_event_level_semantic_name() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();

    for (target, slot_count) in [
        ("MARY_FOMT_US", 1329),
        ("MARY_FOMT_JP", 1329),
        ("MARY_MFOMT_US", 1416),
        ("MARY_MFOMT_JP", 1416),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();

        for script_id in 0..slot_count {
            if symbols.text_count(script_id) == 0 {
                continue;
            }

            let name = symbols
                .script_name(script_id)
                .unwrap_or_else(|| panic!("{target}: script {script_id:04} has text but no name"));
            assert_ne!(
                name,
                format!("EventScript_{script_id:04}"),
                "{target}: text-bearing script {script_id:04} still uses its numbered placeholder"
            );
        }
    }
}

#[test]
fn tv_shopping_phone_order_texts_use_stable_role_names_for_all_targets() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let required_roles = [
        "PendingOrderAwaitingDelivery",
        "PhoneInspection",
        "PhoneCallCostPrompt",
        "ChoiceMakePhoneCall",
        "ChoiceCancelPhoneCall",
        "InsufficientFundsForPhoneCall",
        "TVShoppingNetworkGreeting",
        "MirrorPurchasePrompt",
        "MirrorPurchaseOption",
        "NoItemAvailableForSale",
        "PurchaseConfirmedDeliveryInTwoToThreeDays",
        "InsufficientFundsForPurchase",
        "PurchaseDeclinedCallAgainLater",
    ];
    let prefix = "gText_TV_Shopping_PhoneOrder_";

    for (target, script_id) in [
        ("MARY_FOMT_US", 285),
        ("MARY_FOMT_JP", 285),
        ("MARY_MFOMT_US", 294),
        ("MARY_MFOMT_JP", 294),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let names = symbols
            .names(script_id, symbols.text_count(script_id))
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        for role in required_roles {
            let expected = format!("{prefix}{role}");
            assert!(
                names.contains(&expected),
                "{target}: missing role-based TV-shopping symbol {expected}"
            );
        }
    }

    for obsolete in [
        "YoullHaveToWaitUntilWhat",
        "TheMirrorIs1000GDo",
        "ButImNotSellingAnythingRight",
        "JustGiveMeACallIf",
    ] {
        assert!(
            !source.contains(obsolete),
            "obsolete sentence-fragment symbol remains: {obsolete}"
        );
    }
}

#[test]
fn church_confessional_texts_distinguish_choices_forgiveness_and_rejection() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let prefix = "gText_LocationInteraction_ChurchConfessional_";
    let common_roles = [
        "ChoiceConfessInsufficientSleep",
        "ChoiceConfessOverworkingHarvestSprites",
        "InsufficientSleepConfessionForgiven",
        "InsufficientSleepConfessionRejected",
        "OverworkingHarvestSpritesConfessionForgiven",
        "OverworkingHarvestSpritesConfessionRejected",
        "NeglectingAnimalsConfessionForgiven",
        "NeglectingAnimalsConfessionRejected",
        "WorkingUntilCollapseConfessionForgiven",
        "WorkingUntilCollapseConfessionRejected",
        "ForgivesPoorRelationsAndImprovesFriendship",
        "PoorRelationsConfessionRejected",
        "AnimalCrueltyConfessionForgiven",
        "AnimalCrueltyConfessionRejected",
        "ForgivesSleepingLateAndReducesFatigue",
        "SleepingLateConfessionRejected",
        "LitteringConfessionForgiven",
        "LitteringConfessionRejected",
    ];

    for (target, script_id, spouse) in [
        ("MARY_FOMT_US", 139, "HarvestGoddess"),
        ("MARY_FOMT_JP", 139, "HarvestGoddess"),
        ("MARY_MFOMT_US", 147, "Kappa"),
        ("MARY_MFOMT_JP", 147, "Kappa"),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let names = symbols
            .names(script_id, symbols.text_count(script_id))
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        for role in common_roles {
            let expected = format!("{prefix}{role}");
            assert!(names.contains(&expected), "{target}: missing {expected}");
        }
        for role in [
            format!("ChoiceConfessDesireToMarry{spouse}"),
            format!("{spouse}MarriageConfessionForgiven"),
            format!("{spouse}MarriageConfessionRejected"),
        ] {
            let expected = format!("{prefix}{role}");
            assert!(names.contains(&expected), "{target}: missing {expected}");
        }
    }

    for obsolete in [
        "IHardlyGetAnySleep",
        "SleepIsVeryImportantForEveryone",
        "TheHumanHeartIsAWeak",
        "ThrowingAwayYourOwnGarbageShould",
    ] {
        assert!(
            !source.contains(obsolete),
            "obsolete confession text fragment remains: {obsolete}"
        );
    }
}

