#[test]
fn jeff_dialogue_roles_follow_location_friendship_and_version_control_flow() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let prefix = "gText_NPCEvent_Jeff_DialogueAndGiftResponses_";
    let shared_location_roles = [
        "SupermarketBackRoomAfterClosing",
        "SupermarketBackRoomLowFriendshipFirstConversation",
        "SupermarketBackRoomLowFriendshipRepeatConversation",
        "SupermarketBackRoomMediumFriendshipFirstConversation",
        "SupermarketBackRoomMediumFriendshipRepeatConversation",
        "SupermarketBackRoomHighFriendshipFirstConversation",
        "SupermarketBackRoomHighFriendshipRepeatConversation",
        "SupermarketLowFriendshipFirstConversation",
        "SupermarketLowFriendshipRepeatConversation",
        "SupermarketMediumFriendshipFirstConversation",
        "SupermarketMediumFriendshipRepeatConversation",
        "SupermarketHighFriendshipFirstConversation",
        "SupermarketHighFriendshipRepeatConversation",
        "NorthSideTownGoingToChurch",
        "NorthSideTownTuesdayGoingToClinic",
        "NorthSideTownGoingToInn",
        "ChurchFirstConversation",
        "ChurchRepeatConversation",
        "ClinicFirstConversation",
        "ClinicRepeatConversation",
        "InnFirstConversation",
        "InnRepeatConversation",
    ]
    .map(|role| format!("{prefix}{role}"));

    for (target, script_id) in [
        ("MARY_FOMT_US", 1007),
        ("MARY_FOMT_JP", 1007),
        ("MARY_MFOMT_US", 1077),
        ("MARY_MFOMT_JP", 1077),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let names = symbols
            .names(script_id, symbols.text_count(script_id))
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        assert_eq!(
            &names[..3],
            &[
                format!("{prefix}IntroductionNervousGreeting"),
                format!("{prefix}Introduction"),
                format!("{prefix}BirthdayGiftAcknowledgement"),
            ],
            "{target}: Jeff introduction and birthday roles must retain physical order"
        );
        assert!(
            names
                .windows(shared_location_roles.len())
                .any(|window| window == shared_location_roles),
            "{target}: Jeff location and friendship matrix must retain physical order"
        );

        if target.starts_with("MARY_FOMT_") {
            assert!(names.contains(&format!("{prefix}KarenChildBornFirstConversation")));
            assert!(names.contains(&format!("{prefix}KarenChildBornRepeatConversation")));
            assert!(!names
                .iter()
                .any(|name| name.contains("ForgetMeNotValleyArtistDialogue")));
        } else {
            assert!(!names.iter().any(|name| name.contains("KarenChildBorn")));
            assert!(names.contains(&format!(
                "{prefix}GameCubeLinkForgetMeNotValleyArtistDialoguePart1"
            )));
            assert!(names.contains(&format!(
                "{prefix}GameCubeLinkForgetMeNotValleyArtistDialoguePart2"
            )));
        }
    }
}

