    for target in ["MARY_MFOMT_US", "MARY_MFOMT_JP"] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let names = symbols
            .names(1078, symbols.text_count(1078))
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        assert!(!names.iter().any(|name| {
            name.contains("PlayerSpouseFarmhouse")
                || name.contains("PlayerSpouseSupermarket")
                || name.ends_with("PlayerSpouseStarryNightEveReminder")
        }));
    }
