#[test]
fn fomt_karen_non_spouse_dialogue_roles_follow_marriage_and_love_control_flow() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let prefix = "gText_NPCEvent_Karen_DialogueAndGiftResponses_";
    let rival_spouse_roles = [
        "RivalSpouseFirstConversation",
        "RivalSpousePlayerMarriedOtherSunnyRepeatConversation",
        "RivalSpousePlayerSingleSunnyRepeatConversation",
        "RivalSpouseRainyRepeatConversation",
    ]
    .map(|role| format!("{prefix}{role}"));
    for target in ["MARY_FOMT_US", "MARY_FOMT_JP"] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let names = symbols
            .names(1008, symbols.text_count(1008))
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        assert!(
            names
                .windows(rival_spouse_roles.len())
                .any(|window| window == rival_spouse_roles),
            "{target}: Karen rival-spouse branches must retain physical order"
        );
        let purple_first_role = if target == "MARY_FOMT_US" {
            "UnmarriedSupermarketPurpleHeartFirstOrNorthSideTownMorningConversation"
        } else {
            "UnmarriedSupermarketPurpleHeartFirstConversation"
        };
        let fiance_and_heart_roles = [
            "PlayerFianceSupermarketFirstConversation",
            "PlayerFianceSupermarketRepeatConversation",
            "UnmarriedSupermarketBlackHeartFirstConversation",
            "UnmarriedSupermarketBlackHeartRepeatConversation",
            purple_first_role,
            "UnmarriedSupermarketPurpleHeartRepeatConversation",
            "UnmarriedSupermarketBlueHeartFirstConversation",
            "UnmarriedSupermarketBlueHeartRepeatConversation",
            "UnmarriedSupermarketGreenHeartFirstConversation",
            "UnmarriedSupermarketGreenHeartRepeatConversation",
            "UnmarriedSupermarketYellowHeartFirstConversation",
            "UnmarriedSupermarketYellowHeartRepeatConversation",
            "UnmarriedSupermarketOrangeHeartFirstConversation",
            "UnmarriedSupermarketOrangeHeartRepeatConversation",
            "UnmarriedSupermarketRedHeartFirstConversation",
            "UnmarriedSupermarketRedHeartRepeatConversation",
        ]
        .map(|role| format!("{prefix}{role}"));
        assert!(
            names
                .windows(fiance_and_heart_roles.len())
                .any(|window| window == fiance_and_heart_roles),
            "{target}: Karen fiance and unmarried-heart roles must retain order"
        );

        let married_other_roles = if target == "MARY_FOMT_US" {
            vec![
                format!("{prefix}PlayerMarriedOtherLowOrMediumFriendshipFirstConversation"),
                format!("{prefix}PlayerMarriedOtherLowFriendshipRepeatConversation"),
                format!("{prefix}PlayerMarriedOtherMediumFriendshipRepeatConversation"),
                format!("{prefix}PlayerMarriedOtherHighFriendshipFirstConversation"),
                format!("{prefix}PlayerMarriedOtherHighFriendshipRepeatConversation"),
            ]
        } else {
            vec![
                format!("{prefix}PlayerMarriedOtherLowFriendshipFirstConversation"),
                format!("{prefix}PlayerMarriedOtherLowFriendshipRepeatConversation"),
                format!("{prefix}PlayerMarriedOtherMediumFriendshipFirstConversation"),
                format!("{prefix}PlayerMarriedOtherMediumFriendshipRepeatConversation"),
                format!("{prefix}PlayerMarriedOtherHighFriendshipFirstConversation"),
                format!("{prefix}PlayerMarriedOtherHighFriendshipRepeatConversation"),
            ]
        };
        assert!(
            names
                .windows(married_other_roles.len())
                .any(|window| window == married_other_roles),
            "{target}: Karen player-married-other friendship roles must preserve region topology"
        );
    }
}

