#[test]
fn ann_introduction_birthday_proposal_and_starry_night_roles_follow_family_rules() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let prefix = "gText_NPCEvent_Ann_DialogueAndGiftResponses_";

    for (target, script_id, leading, proposal) in [
        (
            "MARY_FOMT_US",
            1011,
            vec![
                "Introduction",
                "PlayerSpouseBirthdayGiftAcknowledgement",
                "BirthdayGiftAcknowledgement",
                "PlayerSpouseBirthdayAccessoryOrCosmeticGiftResponse",
                "RivalSpouseBirthdayAccessoryOrCosmeticGiftResponse",
                "UnmarriedBirthdayAccessoryOrCosmeticGiftResponse",
            ],
            vec![
                "ProposalAcceptedResponse",
                "RivalSpouseBlueFeatherResponse",
                "IneligibleBlueFeatherResponse",
                "StarryNightInvitation",
                "StarryNightAcceptChoice",
                "StarryNightDeclineChoice",
                "StarryNightAcceptanceResponse",
                "StarryNightDeclineResponse",
            ],
        ),
        (
            "MARY_FOMT_JP",
            1011,
            vec![
                "Introduction",
                "PlayerSpouseBirthdayGiftAcknowledgement",
                "BirthdayGiftAcknowledgement",
                "PlayerSpouseBirthdayAccessoryOrCosmeticGiftResponse",
                "RivalSpouseBirthdayAccessoryOrCosmeticGiftResponse",
                "UnmarriedBirthdayAccessoryOrCosmeticGiftResponse",
            ],
            vec![
                "ProposalAcceptedResponse",
                "RivalSpouseBlueFeatherResponse",
                "IneligibleBlueFeatherResponse",
                "StarryNightInvitation",
                "StarryNightAcceptChoice",
                "StarryNightDeclineChoice",
                "StarryNightAcceptanceResponse",
                "StarryNightDeclineResponse",
            ],
        ),
        (
            "MARY_MFOMT_US",
            1081,
            vec![
                "Introduction",
                "BirthdayGiftAcknowledgement",
                "RivalSpouseBirthdayAccessoryOrCosmeticGiftResponse",
                "UnmarriedBirthdayAccessoryOrCosmeticGiftResponse",
            ],
            vec![
                "RivalSpouseBlueFeatherResponse",
                "StarryNightInvitation",
                "StarryNightAcceptChoice",
                "StarryNightDeclineChoice",
                "StarryNightAcceptanceResponse",
                "StarryNightDeclineResponse",
            ],
        ),
        (
            "MARY_MFOMT_JP",
            1081,
            vec![
                "Introduction",
                "BirthdayGiftAcknowledgement",
                "RivalSpouseBirthdayAccessoryOrCosmeticGiftResponse",
                "UnmarriedBirthdayAccessoryOrCosmeticGiftResponse",
            ],
            vec![
                "RivalSpouseBlueFeatherResponse",
                "StarryNightInvitation",
                "StarryNightAcceptChoice",
                "StarryNightDeclineChoice",
                "StarryNightAcceptanceResponse",
                "StarryNightDeclineResponse",
            ],
        ),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let names = symbols
            .names(script_id, symbols.text_count(script_id))
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        let leading = leading
            .into_iter()
            .map(|role| format!("{prefix}{role}"))
            .collect::<Vec<_>>();
        let proposal = proposal
            .into_iter()
            .map(|role| format!("{prefix}{role}"))
            .collect::<Vec<_>>();
        assert_eq!(
            &names[..leading.len()],
            leading,
            "{target}: Ann leading roles"
        );
        assert!(
            names
                .windows(proposal.len())
                .any(|window| window == proposal),
            "{target}: Ann proposal and Starry Night roles"
        );
        for role in [
            "UnmarriedPerfumeGiftResponsePart1",
            "UnmarriedPerfumeGiftResponsePart2",
        ] {
            assert!(
                names.contains(&format!("{prefix}{role}")),
                "{target}: missing Ann unmarried perfume response role {role}"
            );
        }
    }

    for stale in [
        "Ann_DialogueAndGiftResponses_SorryDoIKnowYouAh",
        "Ann_DialogueAndGiftResponses_DoesThatMeanWhatIThink",
        "Ann_DialogueAndGiftResponses_ComeOverToMyHouseTomorrow",
        "Ann_DialogueAndGiftResponses_IReallyDontHaveAnyUse",
        "Ann_DialogueAndGiftResponses_ButYouReallyWantToGive",
    ] {
        assert!(
            !source.contains(stale),
            "stale dialogue-derived Ann role: {stale}"
        );
    }
}

