#[test]
fn mfomt_village_girls_cooking_request_texts_follow_control_flow_roles() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for target in ["MARY_MFOMT_US", "MARY_MFOMT_JP"] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        for (slot, npc) in [
            (926, "Popuri"),
            (927, "Karen"),
            (928, "Ann"),
            (929, "Mary"),
            (930, "Elli"),
        ] {
            let prefix = format!("gText_NPCEvent_VillageGirlsCookingRequest_{npc}OrderChoice_");
            let names = symbols.names(slot, symbols.text_count(slot));
            assert!(
                names.contains(&Some(format!("{prefix}InitialRequestedDishAnnouncement"))),
                "{target} slot {slot}: missing initial dish announcement"
            );
            assert!(
                names.contains(&Some(format!(
                    "{prefix}RequestedDishReminderAndAbandonPrompt"
                ))),
                "{target} slot {slot}: missing reminder/abandon prompt"
            );
            for role in [
                "PraisesPreviouslyDeliveredDish",
                "ChoiceContinueCooking",
                "ChoiceAbandonRequest",
                "AcceptsRequestedDish",
                "TastesRequestedDish",
                "FinishesMealAfterAllRequestsCompleted",
                "ThanksPlayerAfterAllRequestsCompleted",
                "LeavesAfterCookingRequest",
                "RejectsWrongDishAndOffersAbandonChoice",
                "AcceptsAbandoningRequestAndEndsEvent",
                "EncouragesPlayerToCompleteRequest",
            ] {
                assert!(
                    names.contains(&Some(format!("{prefix}{role}"))),
                    "{target} slot {slot}: missing {role}"
                );
            }
            assert_eq!(
                names
                    .iter()
                    .filter(|name| name.as_deref().is_some_and(|name| {
                        name.starts_with(&format!("{prefix}RequestedDish"))
                            && !name.ends_with("RequestedDishReminderAndAbandonPrompt")
                    }))
                    .count(),
                5,
                "{target} slot {slot}: expected five requested-dish labels"
            );
        }
    }

    for stale in [
        "OrderChoice_WhatIWantToEatIs_02",
        "OrderChoice_ItsDelicious",
        "OrderChoice_IllTry",
        "OrderChoice_WellLetMeTasteIt",
        "OrderChoice_ThisIsNotWhatIOrdered",
        "OrderChoice_ThatsTooBadYouCanTry",
        "OrderChoice_ImLookingForwardToItGood",
    ] {
        assert!(
            !source.contains(stale),
            "stale cooking-request name: {stale}"
        );
    }
}

