#[test]
fn retired_external_tree_is_not_cited_as_evidence() {
    fn inspect(path: &std::path::Path, forbidden: &str, violations: &mut Vec<String>) {
        if path.is_dir() {
            for entry in fs::read_dir(path).unwrap() {
                inspect(&entry.unwrap().path(), forbidden, violations);
            }
            return;
        }
        let extension = path.extension().and_then(|value| value.to_str());
        if !matches!(extension, Some("rs" | "h" | "md" | "sym" | "txt")) {
            return;
        }
        if fs::read_to_string(path)
            .map(|text| text.to_ascii_lowercase().contains(forbidden))
            .unwrap_or(false)
        {
            violations.push(path.display().to_string());
        }
    }

    let forbidden = ["hm", "fomt"].concat();
    let mut violations = Vec::new();
    for root in [
        "src",
        "tests",
        "goodies",
        "docs",
        "README.md",
        "README.zh-CN.md",
    ] {
        inspect(std::path::Path::new(root), &forbidden, &mut violations);
    }
    assert!(
        violations.is_empty(),
        "retired external source tree is still cited in: {violations:?}"
    );
}

#[test]
fn semantic_state_variables_are_typed_or_explicitly_documented() {
    let header = fs::read_to_string("goodies/mary_constants.mary.h").unwrap();
    let typed = header
        .lines()
        .filter_map(|line| {
            line.trim()
                .strip_prefix("mary_var_type(")
                .and_then(|rest| rest.split(',').next())
        })
        .collect::<Vec<_>>();
    let semantic_markers = [
        "_STATE",
        "_RESULT",
        "_CHOICE",
        "_ACTIVE",
        "_KIND",
        "_STATUS",
        "_PHASE",
        "_MODE",
        "_SELECTION",
        "_WEATHER",
        "_SEASON",
        "_DAY_OF_WEEK",
        "_OUTFIT",
        "_GROWTH_STAGE",
    ];
    let mut untyped = header
        .lines()
        .filter_map(|line| {
            let line = line.trim();
            if !line.starts_with("VAR_") || !line.contains('=') {
                return None;
            }
            let name = line.split_whitespace().next().unwrap();
            if semantic_markers.iter().any(|marker| name.contains(marker)) && !typed.contains(&name)
            {
                Some(name.to_owned())
            } else {
                None
            }
        })
        .collect::<Vec<_>>();
    untyped.sort();
    untyped.dedup();
    assert!(
        untyped.is_empty(),
        "semantic state variables lack mary_var_type mappings: {untyped:?}"
    );
}

#[test]
fn unknown_variable_inventory_matches_the_published_audit_counts() {
    let header = fs::read_to_string("goodies/mary_constants.mary.h").unwrap();
    let mut inventories = HashMap::new();
    for (target, expected) in [
        ("MARY_FOMT_US", 24),
        ("MARY_FOMT_JP", 24),
        ("MARY_MFOMT_US", 33),
        ("MARY_MFOMT_JP", 33),
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(&header, &options).unwrap();
        let variable_type = constants.user_type("MaryVarId").unwrap();
        let unknown = (0..2048)
            .filter_map(|id| {
                constants
                    .typed_int_const_name(variable_type, id)
                    .filter(|name| name.starts_with("VAR_UNKNOWN_SLOT_"))
                    .map(|name| (id, name))
            })
            .collect::<Vec<_>>();
        assert_eq!(
            unknown.len(),
            expected,
            "{target}: unknown-variable inventory changed: {unknown:?}"
        );
        for (id, name) in &unknown {
            let named_id = name
                .strip_prefix("VAR_UNKNOWN_SLOT_")
                .unwrap()
                .parse::<i64>()
                .unwrap();
            assert_eq!(
                *id, named_id,
                "{target}: {name} is bound to physical variable slot {id}"
            );
        }
        inventories.insert(
            target,
            unknown
                .into_iter()
                .map(|(id, name)| (id, name.to_owned()))
                .collect::<Vec<_>>(),
        );
    }
    assert_eq!(
        inventories["MARY_FOMT_US"], inventories["MARY_FOMT_JP"],
        "FoMT unknown physical slots differ between US and JP"
    );
    assert_eq!(
        inventories["MARY_MFOMT_US"], inventories["MARY_MFOMT_JP"],
        "MFoMT unknown physical slots differ between US and JP"
    );
    let fomt_ids = inventories["MARY_FOMT_US"]
        .iter()
        .map(|(id, _)| *id)
        .collect::<std::collections::HashSet<_>>();
    let mfomt_ids = inventories["MARY_MFOMT_US"]
        .iter()
        .map(|(id, _)| *id)
        .collect::<std::collections::HashSet<_>>();
    let mut shared_ids = fomt_ids
        .intersection(&mfomt_ids)
        .copied()
        .collect::<Vec<_>>();
    shared_ids.sort_unstable();
    assert_eq!(
        shared_ids,
        [327, 335, 343, 344],
        "FoMT/MFoMT unknown-slot overlap changed: {shared_ids:?}"
    );
}

#[test]
fn same_numbered_unknown_slots_do_not_share_unproven_types_across_game_families() {
    let header = fs::read_to_string("goodies/mary_constants.mary.h").unwrap();
    let callable_header = fs::read_to_string("goodies/mary_callables.mary.h").unwrap();
    for (target, is_fomt) in [
        ("MARY_FOMT_US", true),
        ("MARY_FOMT_JP", true),
        ("MARY_MFOMT_US", false),
        ("MARY_MFOMT_JP", false),
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(&header, &options).unwrap();
        for id in [327, 335, 344] {
            assert_eq!(
                constants.variable_value_type(id),
                None,
                "{target}: same-numbered unknown slot {id} acquired an unproven shared type"
            );
        }
        let expected_type = is_fomt
            .then(|| constants.user_type("MaryBool").unwrap())
            .map(mary::ir::ValueType::UserType);
        assert_eq!(
            constants.variable_value_type(343),
            expected_type,
            "{target}: slot 343 acquired the wrong game-family value type"
        );

        let callables =
            parse_callable_table_with_scope(&callable_header, &options, &constants).unwrap();
        let scripts =
            parse_script_table("mary_script_table { TestUnknown343, };", &options).unwrap();
        let numeric = parse_named_scripts(
            "void TestUnknown343(void) { VarSet(VAR_UNKNOWN_SLOT_327, 1); VarSet(VAR_UNKNOWN_SLOT_335, 1); VarSet(VAR_UNKNOWN_SLOT_343, 1); VarSet(VAR_UNKNOWN_SLOT_344, 1); if (VarGet(VAR_UNKNOWN_SLOT_343) == 1) { return; } }",
            &options,
            &callables.scope,
            &scripts,
        )
        .unwrap();
        let raised =
            decompile_script_named(&numeric.scripts[0].2, &callables.scope, "TestUnknown343")
                .unwrap();
        let source = format_named_script("TestUnknown343", &raised).unwrap();
        assert_eq!(
            source.contains("TRUE"),
            is_fomt,
            "{target}: wrong symbolic output for slot 343: {source}"
        );
        for id in [327, 335, 344] {
            assert!(
                source.contains(&format!("VarSet(VAR_UNKNOWN_SLOT_{id}, 1);")),
                "{target}: untyped slot {id} did not retain its numeric value: {source}"
            );
        }
        let rebuilt = parse_named_scripts(&source, &options, &callables.scope, &scripts).unwrap();
        assert_eq!(
            encode_script(&numeric.scripts[0].2),
            encode_script(&rebuilt.scripts[0].2),
            "{target}: slot 343 symbolic rendering changed bytecode"
        );
    }
}

