#[test]
fn local_enum_types_join_conservatively_across_control_flow() {
    let options = Options::default().define("MARY_FOMT_US").unwrap();
    let constants = parse_constant_header(
        "typedef enum MaryFirst {\n\
         FIRST_ONE = 1,\n\
         } MaryFirst;\n\
         typedef enum MarySecond {\n\
         SECOND_ONE = 1,\n\
         } MarySecond;\n",
        &options,
    )
    .unwrap();
    let callables = parse_callable_table_with_scope(
        "mary_callable_table { GetCondition, GetFirst, GetSecond, }\n\
         int GetCondition(void);\n\
         MaryFirst GetFirst(void);\n\
         MarySecond GetSecond(void);\n",
        &options,
        &constants,
    )
    .unwrap();
    let script_table = parse_script_table("mary_script_table { TestFlow, };\n", &options).unwrap();
    let numeric = parse_named_scripts(
        "void TestFlow(void) {\n\
         int value;\n\
         value = GetFirst();\n\
         if (GetCondition()) { value = GetSecond(); }\n\
         if (value == 1) { GetCondition(); }\n\
         value = GetFirst();\n\
         if (GetCondition()) { value = GetFirst(); }\n\
         if (value == 1) { GetCondition(); }\n\
         value = GetFirst();\n\
         for (int index = 0; index < 1; index++) { value = GetSecond(); }\n\
         if (value == 1) { GetCondition(); }\n\
         do { value = GetSecond(); } while (GetCondition());\n\
         if (value == 1) { GetCondition(); }\n\
         }\n",
        &options,
        &callables.scope,
        &script_table,
    )
    .unwrap();
    let raised =
        decompile_script_named(&numeric.scripts[0].2, &callables.scope, "TestFlow").unwrap();
    let source = format_named_script("TestFlow", &raised).unwrap();
    assert!(source.contains("var_0 == 1"), "{source}");
    assert!(source.contains("var_0 == FIRST_ONE"), "{source}");
    assert!(source.contains("var_0 == SECOND_ONE"), "{source}");
    let symbolic = parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
    assert_eq!(
        encode_script(&numeric.scripts[0].2),
        encode_script(&symbolic.scripts[0].2)
    );
}

#[test]
fn nested_loops_and_early_exits_preserve_only_unambiguous_local_types() {
    let options = Options::default().define("MARY_FOMT_US").unwrap();
    let constants = parse_constant_header(
        "typedef enum MaryFirst {\n\
         FIRST_ONE = 1,\n\
         } MaryFirst;\n\
         typedef enum MarySecond {\n\
         SECOND_ONE = 1,\n\
         } MarySecond;\n",
        &options,
    )
    .unwrap();
    let callables = parse_callable_table_with_scope(
        "mary_callable_table { GetCondition, GetFirst, GetSecond, }\n\
         int GetCondition(void);\n\
         MaryFirst GetFirst(void);\n\
         MarySecond GetSecond(void);\n",
        &options,
        &constants,
    )
    .unwrap();
    let script_table =
        parse_script_table("mary_script_table { TestNestedFlow, };\n", &options).unwrap();
    let numeric = parse_named_scripts(
        "void TestNestedFlow(void) {\n\
         int stable = GetFirst();\n\
         int mixed = GetFirst();\n\
         for (int outer = 0; outer < 2; outer++) {\n\
             for (int inner = 0; inner < 2; inner++) {\n\
                 if (GetCondition()) { return; }\n\
                 if (GetCondition()) { stable = GetFirst(); }\n\
                 switch (GetCondition()) {\n\
                     case 0: mixed = GetFirst(); break;\n\
                     default: mixed = GetSecond(); break;\n\
                 }\n\
             }\n\
         }\n\
         if (stable == 1) { GetCondition(); }\n\
         if (mixed == 1) { GetCondition(); }\n\
         }\n",
        &options,
        &callables.scope,
        &script_table,
    )
    .unwrap();
    let raised =
        decompile_script_named(&numeric.scripts[0].2, &callables.scope, "TestNestedFlow").unwrap();
    let source = format_named_script("TestNestedFlow", &raised).unwrap();
    assert!(
        source.contains("var_0 == FIRST_ONE"),
        "consistent nested-loop type was lost: {source}"
    );
    assert!(
        source.contains("var_1 == 1"),
        "conflicting nested-loop types were not conservatively merged: {source}"
    );
    assert!(
        !source.contains("var_1 == FIRST_ONE") && !source.contains("var_1 == SECOND_ONE"),
        "one branch type leaked through a nested-loop merge: {source}"
    );
    let symbolic = parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
    assert_eq!(
        encode_script(&numeric.scripts[0].2),
        encode_script(&symbolic.scripts[0].2),
        "nested-loop type recovery changed emitted bytecode"
    );
}

#[test]
fn deeply_nested_loops_and_multiple_exits_keep_type_joins_conservative() {
    let options = Options::default().define("MARY_FOMT_US").unwrap();
    let constants = parse_constant_header(
        "typedef enum MaryFirst {\n\
         FIRST_ONE = 1,\n\
         } MaryFirst;\n\
         typedef enum MarySecond {\n\
         SECOND_ONE = 1,\n\
         } MarySecond;\n",
        &options,
    )
    .unwrap();
    let callables = parse_callable_table_with_scope(
        "mary_callable_table { GetCondition, GetFirst, GetSecond, }\n\
         int GetCondition(void);\n\
         MaryFirst GetFirst(void);\n\
         MarySecond GetSecond(void);\n",
        &options,
        &constants,
    )
    .unwrap();
    let scripts = parse_script_table("mary_script_table { TestDeepFlow, };", &options).unwrap();
    let mut input = String::from(
        "void TestDeepFlow(void) { int stable = GetFirst(); int mixed = GetFirst();\n",
    );
    for depth in 0..6 {
        input.push_str(&format!(
            "for (int loop_{depth} = 0; loop_{depth} < 2; loop_{depth}++) {{\n"
        ));
    }
    input.push_str(
        "if (GetCondition()) { return; }\n\
         if (GetCondition()) { stable = GetFirst(); }\n\
         switch (GetCondition()) {\n\
             case 0: mixed = GetFirst(); break;\n\
             case 1: if (GetCondition()) { return; } mixed = GetSecond(); break;\n\
             default: mixed = GetSecond(); break;\n\
         }\n",
    );
    for _ in 0..6 {
        input.push_str("}\n");
    }
    input.push_str(
        "do { if (GetCondition()) { return; } stable = GetFirst(); } while (GetCondition());\n\
         if (stable == 1) { GetCondition(); }\n\
         if (mixed == 1) { GetCondition(); }\n\
         }\n",
    );
    let numeric = parse_named_scripts(&input, &options, &callables.scope, &scripts).unwrap();
    let raised =
        decompile_script_named(&numeric.scripts[0].2, &callables.scope, "TestDeepFlow").unwrap();
    let source = format_named_script("TestDeepFlow", &raised).unwrap();
    assert!(
        source.contains("var_0 == FIRST_ONE"),
        "stable type was lost across deep loops: {source}"
    );
    assert!(
        source.contains("var_1 == 1"),
        "conflicting types leaked through deep-loop exits: {source}"
    );
    assert!(
        !source.contains("var_1 == FIRST_ONE") && !source.contains("var_1 == SECOND_ONE"),
        "a conflicting branch type escaped the deep-loop join: {source}"
    );
    let rebuilt = parse_named_scripts(&source, &options, &callables.scope, &scripts).unwrap();
    assert_eq!(
        encode_script(&numeric.scripts[0].2),
        encode_script(&rebuilt.scripts[0].2),
        "deep-loop type recovery changed emitted bytecode"
    );
}

#[test]
fn switch_fallthrough_and_conditional_reassignment_do_not_leak_enum_types() {
    let options = Options::default().define("MARY_FOMT_US").unwrap();
    let constants = parse_constant_header(
        "typedef enum MaryFirst {\n\
         FIRST_ONE = 1,\n\
         } MaryFirst;\n\
         typedef enum MarySecond {\n\
         SECOND_ONE = 1,\n\
         } MarySecond;\n",
        &options,
    )
    .unwrap();
    let callables = parse_callable_table_with_scope(
        "mary_callable_table { GetCondition, GetFirst, GetSecond, }\n\
         int GetCondition(void);\n\
         MaryFirst GetFirst(void);\n\
         MarySecond GetSecond(void);\n",
        &options,
        &constants,
    )
    .unwrap();
    let scripts = parse_script_table("mary_script_table { TestFallthrough, };", &options).unwrap();
    let numeric = parse_named_scripts(
        "void TestFallthrough(void) {\n\
         int value = GetFirst();\n\
         switch (GetCondition()) {\n\
             case 0:\n\
                 value = GetFirst();\n\
             case 1:\n\
                 if (GetCondition()) { value = GetSecond(); }\n\
                 break;\n\
             default:\n\
                 value = GetFirst();\n\
                 break;\n\
         }\n\
         if (value == 1) { GetCondition(); }\n\
         }\n",
        &options,
        &callables.scope,
        &scripts,
    )
    .unwrap();
    let raised =
        decompile_script_named(&numeric.scripts[0].2, &callables.scope, "TestFallthrough").unwrap();
    let source = format_named_script("TestFallthrough", &raised).unwrap();
    assert!(
        source.contains("var_0 == 1"),
        "fallthrough type conflict did not fall back to an integer: {source}"
    );
    assert!(
        !source.contains("var_0 == FIRST_ONE") && !source.contains("var_0 == SECOND_ONE"),
        "an enum type leaked through a fallthrough merge: {source}"
    );
    let rebuilt = parse_named_scripts(&source, &options, &callables.scope, &scripts).unwrap();
    assert_eq!(
        encode_script(&numeric.scripts[0].2),
        encode_script(&rebuilt.scripts[0].2),
        "fallthrough type recovery changed emitted bytecode"
    );
}

