#[test]
fn local_variable_ids_remain_exact_beyond_one_byte() {
    let options = Options::default().define("MARY_FOMT_US").unwrap();
    let constants = parse_constant_header(
        &fs::read_to_string("goodies/mary_constants.mary.h").unwrap(),
        &options,
    )
    .unwrap();
    let callables = parse_callable_table_with_scope(
        &fs::read_to_string("goodies/mary_callables.mary.h").unwrap(),
        &options,
        &constants,
    )
    .unwrap();
    let script_table =
        parse_script_table("mary_script_table { TestManyLocals, };\n", &options).unwrap();
    let mut input = String::from("void TestManyLocals(void) {\n");
    for index in 0..300 {
        input.push_str(&format!("int local_{index} = {index};\n"));
    }
    input.push_str("if (local_299 == 299) { return; }\n}\n");
    let numeric = parse_named_scripts(&input, &options, &callables.scope, &script_table).unwrap();
    let max_local = numeric.scripts[0]
        .2
        .instructions
        .iter()
        .filter_map(|instruction| match instruction {
            Ins::PushVar(VarId(id)) | Ins::PopVar(VarId(id)) => Some(*id),
            _ => None,
        })
        .max();
    assert_eq!(max_local, Some(299), "unexpected highest compiled local ID");
    let raised =
        decompile_script_named(&numeric.scripts[0].2, &callables.scope, "TestManyLocals").unwrap();
    let source = format_named_script("TestManyLocals", &raised).unwrap();
    assert!(source.contains("var_299 = 299;"), "{source}");
    assert!(source.contains("var_299 == 299"), "{source}");
    let symbolic = parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
    assert_eq!(
        encode_script(&numeric.scripts[0].2),
        encode_script(&symbolic.scripts[0].2),
        "local IDs above 255 changed during Mary-C round-trip"
    );
}

