#[test]
fn presented_item_id_refinement_works_with_direct_discriminator_calls() {
    for target in [
        "MARY_FOMT_US",
        "MARY_FOMT_JP",
        "MARY_MFOMT_US",
        "MARY_MFOMT_JP",
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(
            &fs::read_to_string("goodies/mary_constants.mary.h").unwrap(),
            &options,
        )
        .unwrap();
        let callables = parse_callable_table_with_scope(
            &fs::read_to_string("goodies/mary_callables.mary.h").unwrap(),
            &options,
            &constants,
        )
        .unwrap();
        let script_table =
            parse_script_table("mary_script_table { TestPresentedDirect, };\n", &options).unwrap();
        let numeric = parse_named_scripts(
            "void TestPresentedDirect(void) { int kind = GetPresentedItemKind(); int id = GetPresentedItemId(); if (kind == 0 && id == 0) { TalkClose(); } if (kind != 0 || id == 0) { TalkClose(); } if (GetPresentedItemKind() == 0) { switch (GetPresentedItemId()) { case 0: break; default: break; } } else { if (GetPresentedItemKind() == 1) { switch (GetPresentedItemId()) { case 0: break; default: break; } } } if (GetPresentedItemKind() == 0 && GetPresentedItemId() == 0) { TalkClose(); } if (GetPresentedItemKind() != 0 || GetPresentedItemId() == 0) { TalkClose(); } switch (GetPresentedItemKind()) { case 0: switch (GetPresentedItemId()) { case 0: break; default: break; } break; case 1: switch (GetPresentedItemId()) { case 0: break; default: break; } break; default: break; } switch (GetPresentedItemId()) { case 0: return; default: break; } if (id == 0) { TalkClose(); } }\n",
            &options,
            &callables.scope,
            &script_table,
        )
        .unwrap();
        let raised = decompile_script_named(
            &numeric.scripts[0].2,
            &callables.scope,
            "TestPresentedDirect",
        )
        .unwrap();
        let source = format_named_script("TestPresentedDirect", &raised).unwrap();
        for symbol in [
            "HELD_ITEM_KIND_FOOD",
            "case FOOD_TURNIP:",
            "HELD_ITEM_KIND_ARTICLE",
            "case ARTICLE_FLOWER_MOON_DROP:",
        ] {
            assert!(
                source.contains(symbol),
                "{target}: missing {symbol} for direct dependent callable use: {source}"
            );
        }
        assert_eq!(
            source.matches("case 0:").count(),
            1,
            "{target}: branch-only dependent type leaked beyond its discriminator scope: {source}"
        );
        assert_eq!(
            source.matches("FOOD_TURNIP").count(),
            6,
            "{target}: {source}"
        );
        assert!(
            source.contains("var_1 == 0"),
            "{target}: short-circuit local refinement leaked after the condition: {source}"
        );
        assert_eq!(
            source.matches("case ARTICLE_FLOWER_MOON_DROP:").count(),
            2,
            "{target}: {source}"
        );
        let symbolic =
            parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
        assert_eq!(
            encode_script(&numeric.scripts[0].2),
            encode_script(&symbolic.scripts[0].2),
            "{target}: direct dependent callable refinement changed emitted bytecode"
        );
    }
}

#[test]
fn related_callable_type_survives_compound_condition_into_if_body() {
    for target in [
        "MARY_FOMT_US",
        "MARY_FOMT_JP",
        "MARY_MFOMT_US",
        "MARY_MFOMT_JP",
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(
            &fs::read_to_string("goodies/mary_constants.mary.h").unwrap(),
            &options,
        )
        .unwrap();
        let callables = parse_callable_table_with_scope(
            &fs::read_to_string("goodies/mary_callables.mary.h").unwrap(),
            &options,
            &constants,
        )
        .unwrap();
        let script_table =
            parse_script_table("mary_script_table { TestCompoundBody, };", &options).unwrap();
        let numeric = parse_named_scripts(
            "void TestCompoundBody(void) { int kind = GetPresentedItemKind(); int id = GetPresentedItemId(); if (kind == 0 && IsPresentedItemGiftWrapped()) { switch (id) { case 0: TalkClose(); break; default: break; } } if (!(kind != 0) && IsPresentedItemGiftWrapped()) { switch (id) { case 0: TalkClose(); break; default: break; } } if (kind != 0 || !IsPresentedItemGiftWrapped()) { TalkOpen(); } else { switch (id) { case 0: TalkClose(); break; default: break; } } switch (id) { case 0: return; default: break; } }",
            &options,
            &callables.scope,
            &script_table,
        )
        .unwrap();
        let raised =
            decompile_script_named(&numeric.scripts[0].2, &callables.scope, "TestCompoundBody")
                .unwrap();
        let source = format_named_script("TestCompoundBody", &raised).unwrap();
        assert_eq!(
            source.matches("case FOOD_TURNIP:").count(),
            3,
            "{target}: compound/negated refinements did not reach every logically constrained branch: {source}"
        );
        assert_eq!(
            source.matches("case 0:").count(),
            1,
            "{target}: branch-only dependent type leaked after the if: {source}"
        );
        let rebuilt =
            parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
        assert_eq!(
            encode_script(&numeric.scripts[0].2),
            encode_script(&rebuilt.scripts[0].2),
            "{target}: compound-condition refinement changed emitted bytecode"
        );
    }
}

#[test]
fn conflicting_related_types_in_one_compound_path_stay_numeric() {
    for target in [
        "MARY_FOMT_US",
        "MARY_FOMT_JP",
        "MARY_MFOMT_US",
        "MARY_MFOMT_JP",
    ] {
        let options = Options::default().define(target).unwrap();
        let mut constants_source = fs::read_to_string("goodies/mary_constants.mary.h").unwrap();
        // Test-only metadata makes the wrapping predicate assign the article
        // domain to the same value callable whose item-kind relation assigns
        // the food domain. A true AND path proves both facts, so selecting
        // either domain would depend on traversal order rather than evidence.
        constants_source.push_str(
            "\nmary_callable_return_type_when_callable(GetPresentedItemId, IsPresentedItemGiftWrapped, TRUE, MaryArticleId);\n",
        );
        let constants = parse_constant_header(&constants_source, &options).unwrap();
        let callables = parse_callable_table_with_scope(
            &fs::read_to_string("goodies/mary_callables.mary.h").unwrap(),
            &options,
            &constants,
        )
        .unwrap();
        let script_table =
            parse_script_table("mary_script_table { TestCompoundConflict, };", &options).unwrap();
        let numeric = parse_named_scripts(
            "void TestCompoundConflict(void) { int kind = GetPresentedItemKind(); int wrapped = IsPresentedItemGiftWrapped(); int id = GetPresentedItemId(); if (kind == 0 && wrapped == 1) { switch (id) { case 0: TalkClose(); break; default: break; } } }",
            &options,
            &callables.scope,
            &script_table,
        )
        .unwrap();
        let raised = decompile_script_named(
            &numeric.scripts[0].2,
            &callables.scope,
            "TestCompoundConflict",
        )
        .unwrap();
        let source = format_named_script("TestCompoundConflict", &raised).unwrap();
        assert!(
            source.contains("case 0:"),
            "{target}: conflicting compound refinements must keep the value numeric: {source}"
        );
        for forbidden in ["case FOOD_TURNIP:", "case ARTICLE_FLOWER_MOON_DROP:"] {
            assert!(
                !source.contains(forbidden),
                "{target}: compound refinement selected an arbitrary domain ({forbidden}): {source}"
            );
        }
        let rebuilt =
            parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
        assert_eq!(
            encode_script(&numeric.scripts[0].2),
            encode_script(&rebuilt.scripts[0].2),
            "{target}: conflicting compound refinement changed emitted bytecode"
        );
    }
}

#[test]
fn boolean_discriminator_truth_paths_refine_related_returns() {
    for target in [
        "MARY_FOMT_US",
        "MARY_FOMT_JP",
        "MARY_MFOMT_US",
        "MARY_MFOMT_JP",
    ] {
        let options = Options::default().define(target).unwrap();
        let mut constants_source = fs::read_to_string("goodies/mary_constants.mary.h").unwrap();
        constants_source.push_str(
            "\nmary_callable_return_type_when_callable(GetPresentedItemId, IsPresentedItemGiftWrapped, TRUE, MaryArticleId);\n",
        );
        constants_source.push_str(
            "mary_callable_return_type_when_callable(GetPresentedItemId, IsPresentedItemGiftWrapped, FALSE, MaryFoodId);\n",
        );
        let constants = parse_constant_header(&constants_source, &options).unwrap();
        let callables = parse_callable_table_with_scope(
            &fs::read_to_string("goodies/mary_callables.mary.h").unwrap(),
            &options,
            &constants,
        )
        .unwrap();
        let script_table =
            parse_script_table("mary_script_table { TestBooleanPaths, };", &options).unwrap();
        let numeric = parse_named_scripts(
            "void TestBooleanPaths(void) { int wrapped = IsPresentedItemGiftWrapped(); int id = GetPresentedItemId(); if (wrapped) { switch (id) { case 0: TalkOpen(); break; default: break; } } if (!wrapped) { switch (id) { case 0: TalkClose(); break; default: break; } } if (IsPresentedItemGiftWrapped()) { switch (GetPresentedItemId()) { case 0: TalkOpen(); break; default: break; } } if (!IsPresentedItemGiftWrapped()) { switch (GetPresentedItemId()) { case 0: TalkClose(); break; default: break; } } switch (id) { case 0: return; default: break; } }",
            &options,
            &callables.scope,
            &script_table,
        )
        .unwrap();
        let raised =
            decompile_script_named(&numeric.scripts[0].2, &callables.scope, "TestBooleanPaths")
                .unwrap();
        let source = format_named_script("TestBooleanPaths", &raised).unwrap();
        assert_eq!(
            source.matches("case ARTICLE_FLOWER_MOON_DROP:").count(),
            2,
            "{target}: true boolean paths did not recover the article domain: {source}"
        );
        assert_eq!(
            source.matches("case FOOD_TURNIP:").count(),
            2,
            "{target}: false boolean paths did not recover the food domain: {source}"
        );
        assert_eq!(
            source.matches("case 0:").count(),
            1,
            "{target}: boolean branch refinement leaked beyond its path: {source}"
        );
        let rebuilt =
            parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
        assert_eq!(
            encode_script(&numeric.scripts[0].2),
            encode_script(&rebuilt.scripts[0].2),
            "{target}: boolean discriminator refinement changed emitted bytecode"
        );
    }
}

