#[test]
fn anniversary_date_dialogue_texts_use_choice_and_outcome_roles() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, scripts) in [
        (
            "MARY_FOMT_US",
            &[
                (589usize, "Popuri"),
                (593, "Ann"),
                (597, "Elli"),
                (601, "Karen"),
                (605, "Mary"),
            ][..],
        ),
        (
            "MARY_FOMT_JP",
            &[
                (589usize, "Popuri"),
                (593, "Ann"),
                (597, "Elli"),
                (601, "Karen"),
                (605, "Mary"),
            ][..],
        ),
        (
            "MARY_MFOMT_US",
            &[
                (598usize, "Kai"),
                (602, "Cliff"),
                (606, "Doctor"),
                (610, "Rick"),
                (614, "Gray"),
                (868, "Won"),
            ][..],
        ),
        (
            "MARY_MFOMT_JP",
            &[
                (598usize, "Kai"),
                (602, "Cliff"),
                (606, "Doctor"),
                (610, "Rick"),
                (614, "Gray"),
                (868, "Won"),
            ][..],
        ),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let count = if target.contains("MFOMT") { 11 } else { 9 };
        for (slot, spouse) in scripts {
            let names = symbols.names(*slot, count);
            let prefix = format!("gText_FamilyEvent_{spouse}_AnniversaryDateDialogueChoice_");
            for role in [
                "OpeningQuestion",
                "SpouseBirthdayChoice",
                "WeddingAnniversaryChoice",
                "PlayerBirthdayChoice",
                "IncorrectSpouseBirthdayResponse",
                "CorrectAnniversaryResponse",
                "HandsOccupiedDeferredGiftPrompt",
                "IncorrectPlayerBirthdayResponse",
            ] {
                let expected = format!("{prefix}{role}");
                assert!(
                    names.iter().flatten().any(|name| name == &expected),
                    "{target} slot {slot:04} lacks {expected}"
                );
            }
        }
    }
}

