#[test]
fn clinic_examination_result_values_and_generated_symbols_stay_aligned() {
    let header = fs::read_to_string("goodies/mary_constants.mary.h").unwrap();
    let results = [
        ("CLINIC_EXAM_RESULT_HEALTHY", 0),
        ("CLINIC_EXAM_RESULT_MODERATE_STAMINA_OR_FATIGUE", 1),
        ("CLINIC_EXAM_RESULT_HIGH_FATIGUE", 2),
        ("CLINIC_EXAM_RESULT_LOW_STAMINA", 3),
        ("CLINIC_EXAM_RESULT_LOW_STAMINA_AND_MODERATE_FATIGUE", 4),
        ("CLINIC_EXAM_RESULT_LOW_STAMINA_AND_HIGH_FATIGUE", 5),
    ];

    assert!(!header.contains("CLINIC_EXAM_RESULT_MILD_FATIGUE"));
    for (name, value) in results {
        assert!(
            header.contains(&format!("    {name} = {value},")),
            "clinic result {value} must retain {name}"
        );
    }

    for directory in ["fomt_us", "fomt_jp", "mfomt_us", "mfomt_jp"] {
        let path = Path::new("decompiled_text")
            .join(directory)
            .join("EventScript_ShopEvent_Clinic_ExaminationChoice.mary.c");
        let source = fs::read_to_string(&path).unwrap();
        for (name, _) in results {
            assert!(
                source.contains(&format!("var_1 = {name};")),
                "{} must assign {name}",
                path.display()
            );
            assert!(
                source.contains(&format!("case {name}:")),
                "{} must dispatch {name}",
                path.display()
            );
        }
    }
}

