#[test]
fn mfomt_won_spouse_location_matrices_preserve_ranges_and_region_reuse() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for target in ["MARY_MFOMT_US", "MARY_MFOMT_JP"] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let names = symbols.names(1086, symbols.text_count(1086));
        for location in ["ZackHouse", "MineralBeach", "SouthSideTown"] {
            for heart in ["Yellow", "Orange", "Red"] {
                for occurrence in ["First", "Repeat"] {
                    let expected = format!(
                        "gText_NPCEvent_Won_DialogueAndGiftResponses_PlayerSpouse{location}{heart}Heart{occurrence}Conversation"
                    );
                    assert!(
                        names.iter().any(|name| name.as_deref() == Some(&expected)),
                        "{target}: missing {expected}"
                    );
                }
            }
        }
        for heart in ["Black", "Purple", "Blue", "Green"] {
            for occurrence in ["First", "Repeat"] {
                let expected = format!(
                    "gText_NPCEvent_Won_DialogueAndGiftResponses_PlayerSpouseZackHouse{heart}Heart{occurrence}Conversation"
                );
                assert!(
                    names.iter().any(|name| name.as_deref() == Some(&expected)),
                    "{target}: missing {expected}"
                );
            }
        }
        for location in ["MineralBeach", "SouthSideTown"] {
            for stage in ["Pregnancy", "AfterChildbirth"] {
                for occurrence in ["First", "Repeat"] {
                    let expected = format!(
                        "gText_NPCEvent_Won_DialogueAndGiftResponses_PlayerSpouse{location}{stage}{occurrence}Conversation"
                    );
                    assert!(
                        names.iter().any(|name| name.as_deref() == Some(&expected)),
                        "{target}: missing {expected}"
                    );
                }
            }
        }
        let us_only = [
            "PlayerSpouseSharedFarmhouseGreenHeartMorningRepeatOrSouthSideTownAboveGreenBelowYellowHeartFirstConversation",
            "PlayerSpouseMineralBeachAboveGreenBelowYellowHeartSharedFirstOrRepeatConversation",
        ];
        let jp_only = [
            "PlayerSpouseFarmhouseGreenHeartMorningRepeatConversation",
            "PlayerSpouseMineralBeachAboveGreenBelowYellowHeartFirstConversation",
            "PlayerSpouseMineralBeachAboveGreenBelowYellowHeartRepeatConversation",
            "PlayerSpouseSouthSideTownAboveGreenBelowYellowHeartFirstConversation",
        ];
        for (suffixes, should_exist) in [
            (&us_only[..], target == "MARY_MFOMT_US"),
            (&jp_only[..], target == "MARY_MFOMT_JP"),
        ] {
            for suffix in suffixes {
                let expected = format!("gText_NPCEvent_Won_DialogueAndGiftResponses_{suffix}");
                assert_eq!(
                    names.iter().any(|name| name.as_deref() == Some(&expected)),
                    should_exist,
                    "{target}: region-specific STR topology for {expected}"
                );
            }
        }
    }
}

