#[test]
fn may_dialogue_script_and_text_roles_cover_general_interactions_not_only_joanna_followup() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, slot, count) in [
        ("MARY_FOMT_US", 1029usize, 34usize),
        ("MARY_FOMT_JP", 1029, 34),
        ("MARY_MFOMT_US", 1099, 35),
        ("MARY_MFOMT_JP", 1099, 35),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        assert_eq!(
            symbols.script_name(slot),
            Some("EventScript_NPCEvent_May_DialogueAndGiftResponses"),
            "{target}"
        );
        assert_eq!(symbols.text_count(slot), count, "{target}");
        let names = symbols.names(slot, count);
        for role in [
            "Introduction",
            "BirthdayGiftInitialReaction",
            "BirthdayGiftReflectsOnMissingMother",
            "BlueFeatherAdmirationAndQuestion",
            "GameCubeLinkJoannaPhoneUpdate",
            "SunnySouthTownOrYodelHouseLowFriendshipRepeatConversationBarleyTooBusy",
            "SunnySouthTownOrYodelHouseHighFriendshipRepeatConversationMissesMother",
            "BadWeatherSouthTownOrYodelHouseRepeatConversationRecallsCatchingCold",
            "YodelHouseUpstairsHighFriendshipFirstConversationDreamsOfSleepingOnHay",
            "MothersHillMiddleLowFriendshipFirstConversationExplainsBarleysHotSpringDay",
            "MothersHillMiddleHighFriendshipRepeatConversationMentionsFormerField",
            "NorthTownLowFriendshipFirstConversationComparesCarterAndStu",
            "NorthTownHighFriendshipFirstConversationInvitesPlayerToPlay",
            "NorthTownHighFriendshipPlayerMustWorkResponse",
            "NorthTownHighFriendshipRepeatConversationComplainsAdultsAreBusy",
        ] {
            let expected = format!("gText_NPCEvent_May_DialogueAndGiftResponses_{role}");
            assert!(
                names.iter().flatten().any(|name| name == &expected),
                "{target}: missing {expected}"
            );
        }
        let moving_teddy_bear =
            "gText_NPCEvent_May_DialogueAndGiftResponses_GameCubeLinkMovingTeddyBearRumor";
        assert_eq!(
            names.iter().flatten().any(|name| name == moving_teddy_bear),
            target.starts_with("MARY_MFOMT"),
            "{target}: wrong MFoMT-only link dialogue topology"
        );
    }
    assert!(
        !source.contains("EventScript_NPCEvent_May_PhoneCallWithJoanna_FollowupMayDialogue"),
        "general May dialogue script remains misnamed as one conditional link follow-up"
    );
}

