#[test]
fn jeff_blood_type_correction_preserves_mfomt_spouse_greeting() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, shift, expected_count) in [
        ("MARY_FOMT_US", 0, 11),
        ("MARY_FOMT_JP", 0, 11),
        ("MARY_MFOMT_US", 9, 12),
        ("MARY_MFOMT_JP", 9, 12),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let main_id = 769 + shift;
        assert_eq!(
            symbols.script_name(main_id),
            Some("EventScript_NPCEvent_Jeff_BloodTypeCorrection"),
            "{target}"
        );
        let names = symbols.names(main_id, symbols.text_count(main_id));
        assert_eq!(names.len(), expected_count, "{target}");
        let has = |role: &str| {
            let expected = format!("gText_NPCEvent_Jeff_BloodTypeCorrection_{role}");
            names
                .iter()
                .any(|actual| actual.as_deref() == Some(expected.as_str()))
        };
        assert_eq!(
            has("DoctorGreetsSpouseByNickname"),
            target.contains("MFOMT"),
            "{target}"
        );
        for role in [
            "JeffRejectsCorrectedBloodType",
            "DoctorConfirmsNewResultIsCorrect",
            "DoctorExplainsImportantDiscoveryAboutJeff",
            "JeffExplainsEarlierBloodTypeResultWasWrong",
            "DoctorApologizesForClericalError",
            "JeffSaysOldBloodTypeSeemedToFitPersonality",
        ] {
            assert!(has(role), "{target}: missing {role}");
        }
        for (id, expected) in [
            (
                770 + shift,
                "EventScript_NPCEvent_Jeff_BloodTypeCorrection_FollowupDoctorDialogue",
            ),
            (
                771 + shift,
                "EventScript_NPCEvent_Jeff_BloodTypeCorrection_FollowupJeffDialogue",
            ),
            (
                772 + shift,
                "EventScript_NPCEvent_Jeff_BloodTypeCorrection_FollowupElliDialogue",
            ),
        ] {
            assert_eq!(symbols.script_name(id), Some(expected), "{target}");
        }
    }
    for stale in [
        "BloodTypeCorrection_Doctor_FollowupDialogue",
        "BloodTypeCorrection_Jeff_FollowupDialogue",
        "BloodTypeCorrection_Elli_FollowupDialogue",
        "BloodTypeCorrection_HeyNickNameHowAreYou",
    ] {
        assert!(!source.contains(stale), "stale blood-type role: {stale}");
    }
}

