#[test]
fn one_hundred_question_quiz_answers_are_scoped_by_question_number() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    assert!(
        !source.contains("OneHundredQuestionQuiz_Answer_"),
        "quiz answer symbols must identify their owning question"
    );
    assert!(
        !source.lines().any(|line| {
            line.contains("OneHundredQuestionQuiz_Question")
                && line.contains("Answer_NonverbalReaction")
        }),
        "quiz data must not be mislabeled as a nonverbal character reaction"
    );

    for target in ["MARY_MFOMT_US", "MARY_MFOMT_JP"] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let answer_names = symbols
            .names(1131, symbols.text_count(1131))
            .into_iter()
            .flatten()
            .filter(|name| {
                name.contains("OneHundredQuestionQuiz_Question") && name.contains("_Answer_")
            })
            .collect::<Vec<_>>();
        assert!(
            answer_names.len() >= 600,
            "{target} unexpectedly exposed only {} question-scoped answers",
            answer_names.len()
        );
        assert!(
            answer_names.iter().all(|name| !name.ends_with("_02")
                && !name.ends_with("_03")
                && !name.ends_with("_04")),
            "{target} retained a mechanically numbered quiz answer: {:?}",
            answer_names.iter().find(|name| name.ends_with("_02")
                || name.ends_with("_03")
                || name.ends_with("_04"))
        );
        assert!(
            answer_names.iter().all(|name| {
                !name.split("_Answer_").nth(1).is_some_and(|answer| {
                    answer
                        .strip_prefix("Numbered")
                        .or_else(|| answer.strip_prefix("Number"))
                        .is_some_and(|rest| rest.as_bytes().first().is_some_and(u8::is_ascii_digit))
                })
            }),
            "{target} retained a generated Number/Numbered numeric answer"
        );
    }

    for expected in [
        "Question002_Answer_PhoenixWithTrailingCharacter",
        "Question003_Answer_0Percent",
        "Question003_Answer_About70Percent",
        "Question003_Answer_About90PercentJapaneseResidue",
        "Question003_Answer_100Percent",
        "Question006_Answer_EmptyText",
        "Question009_Answer_Summer7thIndented",
        "Question009_Answer_Fall21stDoubleSpaced",
        "Question015_Answer_Winter28thTypoAs28tj",
        "Question019_Answer_Fall21stTypoAs21th",
        "Question036_Answer_CrucianCarpTypoAsCrucialCarp",
        "Question038_Answer_4GJapaneseResidue",
        "Question040_Answer_38EpisodesWithTrailingSpace",
        "Question056_Answer_LargeSalmon",
        "Question100_Answer_FoiledWithExclamation",
        "Question140_Answer_12Cards",
        "Question250_Answer_0JapaneseResidue",
        "Question251_Answer_ParentsTypoMissingA",
        "Question255_Answer_SnowstormTypoAsSnowstrom",
    ] {
        assert!(
            source.contains(expected),
            "missing physical quiz text distinction: {expected}"
        );
    }
}

#[test]
fn entrance_event_dispatchers_are_named_by_verified_destination_location() {
    let fomt_ids = [
        105, 108, 136, 179, 205, 362, 370, 371, 372, 373, 374, 375, 376, 377, 378, 523, 528, 530,
        560,
    ];
    let mfomt_ids = [
        113, 116, 144, 188, 214, 371, 379, 380, 381, 382, 383, 384, 385, 386, 387, 532, 537, 539,
        569,
    ];
    let locations = [
        "ZackHouse",
        "KaiRestaurant",
        "BehindChurch",
        "GotzHouse",
        "SupermarketBackRoom",
        "HarvestSpritesHut",
        "Church",
        "EllenHouse",
        "Supermarket",
        "MineralClinic1F",
        "Inn1F",
        "BasilHouse1F",
        "Library1F",
        "MayorHouse",
        "AjaWinery1F",
        "PoultryFarmHouse1F",
        "Blacksmith",
        "YodelRanchHouse1F",
        "SouthSideTown",
    ];
    for (target, ids) in [
        ("MARY_FOMT_US", &fomt_ids[..]),
        ("MARY_FOMT_JP", &fomt_ids[..]),
        ("MARY_MFOMT_US", &mfomt_ids[..]),
        ("MARY_MFOMT_JP", &mfomt_ids[..]),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(
            &fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap(),
            &options,
        )
        .unwrap();
        for (&id, &location) in ids.iter().zip(&locations) {
            let role = if [
                "BehindChurch",
                "SupermarketBackRoom",
                "HarvestSpritesHut",
                "MayorHouse",
                "YodelRanchHouse1F",
                "SouthSideTown",
            ]
            .contains(&location)
            {
                "WithAccessGuard"
            } else {
                "WithEventDispatch"
            };
            let expected = format!("EventScript_LocationTransition_Enter{location}{role}");
            assert_eq!(
                symbols.script_name(id),
                Some(expected.as_str()),
                "{target} slot {id}"
            );
            let names = symbols.names(id, symbols.text_count(id));
            let text_suffix = "_DoorIsLocked";
            assert!(
                names.iter().flatten().all(|name| name
                    == &format!("gText_LocationTransition_Enter{location}{role}{text_suffix}")),
                "{target} slot {id}: {names:?}"
            );
        }
    }
}

