#[test]
fn numbered_script_symbols_are_textless_placeholder_slots() {
    let fomt_numbered = [
        4, 14, 15, 80, 81, 82, 83, 84, 570, 835, 836, 837, 838, 839, 840, 841, 868, 869, 870, 871,
        872, 964, 965, 966, 967, 968, 1064, 1327, 1328,
    ];
    let mfomt_numbered = [
        4, 14, 15, 88, 89, 90, 91, 92, 579, 844, 845, 846, 847, 848, 849, 850, 916, 935, 936, 937,
        938, 939, 940, 1032, 1033, 1034, 1035, 1036, 1060, 1102, 1137, 1138, 1156, 1374, 1375,
        1376, 1377, 1378, 1379, 1380, 1383, 1413, 1414, 1415,
    ];
    for (target, slot_count) in [
        ("MARY_FOMT_US", 1329),
        ("MARY_FOMT_JP", 1329),
        ("MARY_MFOMT_US", 1416),
        ("MARY_MFOMT_JP", 1416),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(
            &fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap(),
            &options,
        )
        .unwrap();

        let mut actual_numbered = Vec::new();
        for id in 0..slot_count {
            let Some(name) = symbols.script_name(id) else {
                continue;
            };
            let numbered_name = format!("EventScript_{id:04}");
            if name == numbered_name {
                actual_numbered.push(id);
                assert_eq!(
                    symbols.text_count(id),
                    0,
                    "{target} slot {id} still has text and therefore needs an event-level name"
                );
            }
        }
        let expected: &[usize] = if target.starts_with("MARY_FOMT_") {
            &fomt_numbered
        } else {
            &mfomt_numbered
        };
        assert_eq!(
            actual_numbered, expected,
            "{target}: numbered script inventory changed without an evidence-backed audit update"
        );
    }
}

#[test]
fn raw_integer_callable_arguments_are_an_explicit_audited_inventory() {
    let expected = [
        ("NoOp014", 0),
        ("NoOpAnimalEventEntityInitialization", 1),
        ("NoOpAnimalEventEntityInitialization", 2),
        ("NoOpTutorialEggDefinition", 0),
        ("NoOpTutorialEggDefinition", 1),
        ("NoOpTutorialEggDefinition", 2),
        ("NoOpTutorialEggSelection", 0),
        ("NoOpTutorialFieldObject", 0),
        ("NoOpTutorialFieldObject", 1),
        ("NoOpTutorialFieldObject", 2),
        ("NoOpTutorialFieldTile", 0),
        ("NoOpTutorialFieldTile", 1),
        ("NoOpTutorialFieldTile", 2),
        ("NoOpTutorialFieldTile", 3),
        ("NoOpTutorialFieldTile", 4),
        ("OpenRucksackMenu", 0),
        ("RandomIntInclusive", 0),
        ("RandomIntInclusive", 1),
        ("RemoveFarmHorse", 1),
        ("SetTextVariableNumber", 1),
        ("SetTextVariableNumberFieldWidth", 1),
        ("VarSet", 1),
    ];

    for target in [
        "MARY_FOMT_US",
        "MARY_FOMT_JP",
        "MARY_MFOMT_US",
        "MARY_MFOMT_JP",
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(
            &fs::read_to_string("goodies/mary_constants.mary.h").unwrap(),
            &options,
        )
        .unwrap();
        let callables = parse_callable_table_with_scope(
            &fs::read_to_string("goodies/mary_callables.mary.h").unwrap(),
            &options,
            &constants,
        )
        .unwrap();
        let mut actual =
            callables
                .scope
                .callable_map()
                .iter()
                .flat_map(|(name, (_, shape))| {
                    shape.parameter_types().iter().enumerate().filter_map(
                        move |(index, value_type)| {
                            (*value_type == mary::ir::ValueType::Integer)
                                .then_some((name.as_str(), index))
                        },
                    )
                })
                .collect::<Vec<_>>();
        actual.sort_unstable();

        assert_eq!(
            actual, expected,
            "{target}: raw integer callable arguments changed without an evidence-backed audit"
        );
    }
}

#[test]
fn callable_alias_names_are_a_closed_native_pointer_identity_inventory() {
    for (target, expected) in [
        ("MARY_FOMT_US", Vec::<&str>::new()),
        ("MARY_FOMT_JP", Vec::<&str>::new()),
        ("MARY_MFOMT_US", vec!["SelectMoonViewingPartnerAlias"]),
        ("MARY_MFOMT_JP", vec!["SelectMoonViewingPartnerAlias"]),
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(
            &fs::read_to_string("goodies/mary_constants.mary.h").unwrap(),
            &options,
        )
        .unwrap();
        let callables = parse_callable_table_with_scope(
            &fs::read_to_string("goodies/mary_callables.mary.h").unwrap(),
            &options,
            &constants,
        )
        .unwrap();
        let mut actual = callables
            .scope
            .callable_map()
            .keys()
            .filter(|name| name.ends_with("Alias"))
            .map(String::as_str)
            .collect::<Vec<_>>();
        actual.sort_unstable();
        assert_eq!(
            actual, expected,
            "{target}: alias names require exact same-handler ROM evidence"
        );
    }
}

#[test]
fn text_symbols_are_owned_by_only_one_script_per_target() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, slot_count) in [
        ("MARY_FOMT_US", 1329),
        ("MARY_FOMT_JP", 1329),
        ("MARY_MFOMT_US", 1416),
        ("MARY_MFOMT_JP", 1416),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let mut owners = HashMap::new();
        for script_id in 0..slot_count {
            for text_name in symbols
                .names(script_id, symbols.text_count(script_id))
                .into_iter()
                .flatten()
            {
                if let Some(previous_id) = owners.insert(text_name.clone(), script_id) {
                    panic!(
                        "{target}: text symbol {text_name} is shared by scripts {previous_id} and {script_id}"
                    );
                }
            }
        }
    }
}

#[test]
fn semantic_symbol_table_has_no_unscoped_sentence_derived_text_names() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let sentence_starts = [
        "gText_I",
        "gText_You",
        "gText_We",
        "gText_He",
        "gText_She",
        "gText_They",
        "gText_This",
        "gText_That",
        "gText_What",
        "gText_Why",
        "gText_How",
        "gText_Where",
        "gText_When",
        "gText_Hi",
        "gText_Hello",
        "gText_Oh",
        "gText_Ah",
        "gText_Please",
        "gText_Dont",
        "gText_Cant",
        "gText_Isnt",
        "gText_Lets",
        "gText_Today",
        "gText_Tomorrow",
    ];
    let structured_prefixes = [
        "gText_NPCEvent_",
        "gText_FestivalEvent_",
        "gText_FamilyEvent_",
        "gText_LoveEvent_",
        "gText_RivalEvent_",
        "gText_RivalMarriageEvent_",
        "gText_SystemEvent_",
        "gText_ShopEvent_",
        "gText_LocationInteraction_",
        "gText_LocationTransition_",
        "gText_FarmEvent_",
        "gText_TV_Shopping_",
        "gText_AchievementEvent_",
        "gText_WeddingEvent_",
        "gText_WeatherEvent_",
        "gText_SystemMenu_",
        "gText_TutorialEvent_",
        "gText_CollectibleEvent_",
        "gText_MineEvent_",
    ];

    for line in source.lines() {
        let name = line.trim().trim_end_matches(',');
        if !name.starts_with("gText_") || structured_prefixes.iter().any(|p| name.starts_with(p)) {
            continue;
        }
        assert!(
            !sentence_starts
                .iter()
                .any(|prefix| name.starts_with(prefix)),
            "unscoped sentence-derived text symbol remains: {name}"
        );
    }
}

#[test]
fn semantic_symbol_table_does_not_fall_back_to_mechanical_variant_names() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for legacy_category in [
        "EventScript_FarmInteraction_",
        "EventScript_Minigame_",
        "EventScript_SystemEffect_",
        "EventScript_SystemMessage_",
        "EventScript_Debug_",
        "EventScript_TutorialEvent_MFoMTOpeningFarmOfferAndBadEndingChoice",
        "gText_Minigame_Won_",
        "gText_SystemMessage_",
    ] {
        assert!(
            !source.contains(legacy_category),
            "legacy script category remains: {legacy_category}"
        );
    }
    for line in source.lines() {
        let name = line.trim().trim_end_matches(',');
        if !(name.starts_with("EventScript_") || name.starts_with("gText_")) {
            continue;
        }

        for placeholder in [
            "Variant",
            "Dialogue0",
            "Text0",
            "Message0",
            "Unknown",
            "Primary",
            "Duplicate",
            "Alternate",
        ] {
            assert!(
                !name.contains(placeholder),
                "mechanical or unproven semantic symbol remains: {name}"
            );
        }

        assert!(
            name.matches("Layout").count() <= 1,
            "multiple menu-layout roles were accidentally composed: {name}"
        );
        assert!(
            !(name.contains("WithPopuriPresent") && name.contains("WithPopuriAbsent")),
            "mutually exclusive Popuri-presence roles were accidentally composed: {name}"
        );

        // A trailing _02/_03 was historically used only to silence duplicate
        // names. Real ordering belongs in the event stage (for example
        // BlackHeart_01_Introduction), while numeric quiz answers such as
        // Answer_12 are values rather than variants.
        let trailing_ordinal = name.rsplit_once('_').is_some_and(|(_, suffix)| {
            suffix.len() == 2
                && suffix.starts_with('0')
                && matches!(suffix.as_bytes()[1], b'2'..=b'9')
        });
        assert!(
            !trailing_ordinal,
            "mechanical trailing ordinal remains in semantic symbol: {name}"
        );
    }
}

#[test]
fn every_text_symbol_uses_its_owning_scripts_semantic_domain() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let mut script_domain = None;
    let mut script_subject = None;
    let subject_scoped_domains = [
        "AchievementEvent",
        "CollectibleEvent",
        "FamilyEvent",
        "FarmEvent",
        "FestivalEvent",
        "LoveEvent",
        "MineEvent",
        "MinigameEvent",
        "NPCEvent",
        "RivalEvent",
        "RivalMarriageEvent",
        "ShopEvent",
        "TutorialEvent",
        "WeatherEvent",
        "WeddingEvent",
    ];
    let mut checked = 0;
    let mut subjects_checked = 0;
    for (line_index, line) in source.lines().enumerate() {
        let name = line.trim().trim_end_matches(',');
        if let Some(rest) = name.strip_prefix("EventScript_") {
            let parts = rest
                .split_once('_')
                .filter(|(domain, _)| !domain.chars().all(|ch| ch.is_ascii_digit()));
            script_domain = parts.map(|(domain, _)| domain);
            script_subject = parts.and_then(|(domain, rest)| {
                subject_scoped_domains
                    .contains(&domain)
                    .then(|| rest.split_once('_').map_or(rest, |(subject, _)| subject))
            });
            continue;
        }
        let Some(rest) = name.strip_prefix("gText_") else {
            continue;
        };
        let text_domain = rest.split_once('_').map_or(rest, |(domain, _)| domain);
        let Some(expected) = script_domain else {
            continue;
        };
        checked += 1;
        assert_eq!(
            text_domain,
            expected,
            "line {}: {name} does not use its owning script domain {expected}",
            line_index + 1
        );
        if let Some(expected_subject) = script_subject {
            let text_subject = rest
                .split_once('_')
                .map(|(_, rest)| rest.split_once('_').map_or(rest, |(subject, _)| subject))
                .unwrap_or("");
            subjects_checked += 1;
            assert_eq!(
                text_subject,
                expected_subject,
                "line {}: {name} does not use its owning script subject {expected_subject}",
                line_index + 1
            );
        }
    }
    assert!(
        checked > 10_000,
        "too few owned text symbols checked: {checked}"
    );
    assert!(
        subjects_checked > 7_000,
        "too few subject-scoped text symbols checked: {subjects_checked}"
    );
}

