#[test]
fn mineral_town_friends_profiles_share_structured_symbols_across_all_targets() {
    for (target, script_id) in [
        ("MARY_FOMT_US", 1048),
        ("MARY_FOMT_JP", 1048),
        ("MARY_MFOMT_US", 1119),
        ("MARY_MFOMT_JP", 1119),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(
            &fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap(),
            &options,
        )
        .unwrap();
        assert_eq!(
            symbols.script_name(script_id),
            Some("EventScript_TV_MineralTownFriendsCharacterProfiles"),
            "{target} profile-program script"
        );
        let count = symbols.text_count(script_id);
        assert!(count >= 170, "{target}: only {count} profile text slots");
        let names = symbols.names(script_id, count);
        assert!(
            names
                .iter()
                .flatten()
                .all(|name| name.starts_with("gText_TV_MineralTownFriends_")),
            "{target}: unstructured profile text symbol remains"
        );
        if target.ends_with("_US") {
            let expected = if script_id == 1048 {
                [
                    "gText_TV_MineralTownFriends_SharedBoldOrChefProfile_HarvestSpriteFamilyMemberStaid",
                    "gText_TV_MineralTownFriends_BoldProfile_HarvestSpriteFamilyMemberNappy",
                    "gText_TV_MineralTownFriends_SharedAquaHoggyOrTimidProfile_HarvestSpriteFamilyMemberNappy",
                ]
            } else {
                [
                    "gText_TV_MineralTownFriends_ChefProfile_HarvestSpriteFamilyMemberStaid",
                    "gText_TV_MineralTownFriends_SharedBoldOrChefProfile_HarvestSpriteFamilyMemberNappy",
                    "gText_TV_MineralTownFriends_SharedAquaHoggyOrTimidProfile_HarvestSpriteFamilyMemberNappy",
                ]
            };
            for expected in expected {
                assert!(
                    names.iter().flatten().any(|name| name == expected),
                    "{target}: missing profile-layout role {expected}"
                );
            }
        }
        assert!(names.iter().flatten().all(|name| {
            !name.contains("HarvestSpriteFamilyMemberStaidVariant")
                && !name.contains("HarvestSpriteFamilyMemberNappyVariant")
        }));
    }
}

