#[test]
fn manna_aja_advice_event_preserves_shared_slot_roles() {
    let symbol_source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let source = format!(
        "{}\n{}",
        symbol_source,
        fs::read_to_string("goodies/mary_constants.mary.h").unwrap()
    );
    for (target, script_id) in [
        ("MARY_FOMT_US", 756),
        ("MARY_FOMT_JP", 756),
        ("MARY_MFOMT_US", 765),
        ("MARY_MFOMT_JP", 765),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&symbol_source, &options).unwrap();
        assert_eq!(
            symbols.script_name(script_id),
            Some("EventScript_NPCEvent_Manna_AjasDepartureAdviceFromFriends"),
            "{target}"
        );
        let names = symbols.names(script_id, symbols.text_count(script_id));
        assert_eq!(names.len(), 15, "{target}");
        for (index, role) in [
            "MannaRequestsAdviceAboutAja",
            "SashaAsksWhatTroublesManna",
            "MannaNamesAjaAsConcern",
            "AnnaSaysSheHasNeverMetAja",
            "MannaExplainsAjaLeftAfterArgumentWithDuke",
            "AnnaReactsToAjasDeparture",
            "SashaAsksWhetherAjaKeepsInTouch",
            "MannaWantsAjaToReturnAndReconcile",
            "SashaRespondsToMannasConcern",
            "SashaOffersToCallAja",
            "AnnaSupportsSashasPlan",
            "MannaThanksFriendsForAdvice",
            "SashaSaysFriendsHelpEachOther",
            "AnnaReassuresManna",
            "MannaThanksFriendsAgain",
        ]
        .into_iter()
        .enumerate()
        {
            let expected = format!("gText_NPCEvent_Manna_AjasDepartureAdviceFromFriends_{role}");
            assert_eq!(names[index].as_deref(), Some(expected.as_str()), "{target}");
        }
    }
    for stale in [
        "EventScript_NPCEvent_Manna_DiscussesAjasDeparture_MainScene",
        "gText_NPCEvent_Manna_DiscussesAjasDeparture_MainScene_",
        "SashaSympathizesWithManna",
        "SashaAcknowledgesMannasConcern",
        "VAR_MANNA_DISCUSSING_AJAS_DEPARTURE_EVENT_STATE",
    ] {
        assert!(!source.contains(stale), "stale Manna/Aja identity: {stale}");
    }
}

#[test]
fn fomt_family_date_regional_text_slots_follow_actual_consumers() {
    let symbol_source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, script_id, slot, expected, generated_file, is_called) in [
        (
            "MARY_FOMT_US",
            632,
            13,
            "gText_FamilyEvent_Elli_SpouseBirthdayDinnerDialogueChoice_ElliBabyBirthdayCorrectAnswerReaction",
            "decompiled_text/fomt_us/EventScript_FamilyEvent_Elli_SpouseBirthdayDinnerDialogueChoice.mary.c",
            true,
        ),
        (
            "MARY_FOMT_JP",
            632,
            13,
            "gText_FamilyEvent_Elli_SpouseBirthdayDinnerDialogueChoice_ChoiceBabyBirthday",
            "decompiled_text/fomt_jp/EventScript_FamilyEvent_Elli_SpouseBirthdayDinnerDialogueChoice.mary.c",
            false,
        ),
        (
            "MARY_FOMT_US",
            635,
            14,
            "gText_FamilyEvent_Karen_SpouseBirthdayDinnerDialogueChoice_KarenBabyBirthdayCorrectAnswerCelebration",
            "decompiled_text/fomt_us/EventScript_FamilyEvent_Karen_SpouseBirthdayDinnerDialogueChoice.mary.c",
            true,
        ),
        (
            "MARY_FOMT_JP",
            635,
            14,
            "gText_FamilyEvent_Karen_SpouseBirthdayDinnerDialogueChoice_KarenLaughsAtWrongBirthdayAnswer",
            "decompiled_text/fomt_jp/EventScript_FamilyEvent_Karen_SpouseBirthdayDinnerDialogueChoice.mary.c",
            true,
        ),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&symbol_source, &options).unwrap();
        let names = symbols.names(script_id, symbols.text_count(script_id));
        assert_eq!(
            names[slot].as_deref(),
            Some(expected),
            "{target} script {script_id} text slot {slot}"
        );

        if std::path::Path::new(generated_file).is_file() {
            let generated = fs::read_to_string(generated_file).unwrap();
            assert_eq!(
                generated.contains(&format!("TalkMessage({expected})")),
                is_called,
                "{target} script {script_id} physical text consumer"
            );
        }
    }
}

#[test]
fn popuri_player_birthday_dinner_preserves_regional_text_pool_order() {
    let symbol_source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let prefix = "gText_FamilyEvent_Popuri_PlayerBirthdayDinnerDialogueChoice_";
    let us_roles = [
        "HappyBirthdayIveBeenPlanningThis",
        "IHadSoMuchFunToday",
        "HowCanYouConfuseMyBirthday",
        "BabySBirthday",
        "LetsAlwaysBeTogether",
    ];
    let jp_roles = [
        "HappyBirthdayIveBeenPlanningThis",
        "LetsAlwaysBeTogether",
        "IHadSoMuchFunToday",
        "HowCanYouConfuseMyBirthday",
        "BabySBirthday",
    ];

    for (target, expected_roles) in [("MARY_FOMT_US", us_roles), ("MARY_FOMT_JP", jp_roles)] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&symbol_source, &options).unwrap();
        let names = symbols.names(640, symbols.text_count(640));
        assert_eq!(names.len(), 16, "{target}: physical text count");
        let expected = expected_roles
            .map(|role| Some(format!("{prefix}{role}")))
            .to_vec();
        assert_eq!(&names[9..14], expected, "{target}: physical slots 9..13");

        let mut actual_set = names[9..14]
            .iter()
            .flatten()
            .map(String::as_str)
            .collect::<Vec<_>>();
        let mut expected_set = us_roles
            .iter()
            .map(|role| format!("{prefix}{role}"))
            .collect::<Vec<_>>();
        actual_set.sort_unstable();
        expected_set.sort_unstable();
        assert_eq!(actual_set, expected_set, "{target}: shared semantic roles");
    }
}

#[test]
fn lillia_and_sasha_marriage_reminiscence_preserves_speakers_and_roles() {
    let symbol_source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, shift) in [
        ("MARY_FOMT_US", 0),
        ("MARY_FOMT_JP", 0),
        ("MARY_MFOMT_US", 9),
        ("MARY_MFOMT_JP", 9),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&symbol_source, &options).unwrap();
        let main_id = 760 + shift;
        let main_names = symbols.names(main_id, symbols.text_count(main_id));
        for (index, role) in [
            "LilliaRemarksOnSashaAndJeffsLongMarriage",
            "SashaConfirmsLongMarriage",
            "LilliaRecallsSashaAndJeffWereChildhoodFriends",
            "SashaRecallsJeffAlwaysDependedOnHer",
            "LilliaRecallsJeffAlwaysStayedBehindSasha",
            "SashaRecallsJeffHidingBehindHerWhenScared",
            "LilliaRecallsSashaProtectingJeffFromDuke",
            "SashaRecallsStandingUpToDukeForJeff",
            "SashaAppreciatesJeffAsHusbandAndFather",
            "LilliaTeasesSashaForSentimentalStory",
            "SashaRespondsToLilliasTeasing",
        ]
        .into_iter()
        .enumerate()
        {
            let expected =
                format!("gText_NPCEvent_LilliaAndSasha_ReminisceAboutJeffsMarriage_{role}");
            assert_eq!(
                main_names[index].as_deref(),
                Some(expected.as_str()),
                "{target} main role {index}"
            );
        }

        for (script_id, script_name, roles) in [
            (
                761 + shift,
                "EventScript_NPCEvent_LilliaAndSasha_ReminisceAboutJeffsMarriage_FollowupLilliaDialogue",
                [
                    "LilliaValuesHavingHusbandByHerSide",
                    "LilliaSaysSashaAndJeffMakeAGoodCouple",
                ],
            ),
            (
                762 + shift,
                "EventScript_NPCEvent_LilliaAndSasha_ReminisceAboutJeffsMarriage_FollowupSashaDialogue",
                [
                    "SashaIsEmbarrassedPlayerOverheard",
                    "SashaSaysSheCouldNeverLeaveJeffAlone",
                ],
            ),
        ] {
            assert_eq!(symbols.script_name(script_id), Some(script_name), "{target}");
            let names = symbols.names(script_id, symbols.text_count(script_id));
            for (index, role) in roles.into_iter().enumerate() {
                let expected = format!("gText_NPCEvent_LilliaAndSasha_ReminisceAboutJeffsMarriage_Followup{}Dialogue_{role}", if script_id == 761 + shift { "Lillia" } else { "Sasha" });
                assert_eq!(
                    names[index].as_deref(),
                    Some(expected.as_str()),
                    "{target} followup {script_id} role {index}"
                );
            }
        }
    }

    for stale in [
        "_YouAndJeffHaveBeenMarried",
        "_LilliaInvitesSashaBackAnytime",
        "_FollowupLilliaDialogue_ItsNiceToHaveYourHusband",
        "_FollowupSashaDialogue_WereYouListeningHowEmbarrassing",
    ] {
        assert!(
            !symbol_source.contains(stale),
            "stale reminiscence role: {stale}"
        );
    }
}

