#[test]
fn cliff_snow_collapse_preserves_photo_and_doctor_spouse_branch() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, shift, expected_count) in [
        ("MARY_FOMT_US", 0, 8),
        ("MARY_FOMT_JP", 0, 8),
        ("MARY_MFOMT_US", 9, 9),
        ("MARY_MFOMT_JP", 9, 9),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let main_id = 781 + shift;
        let names = symbols.names(main_id, symbols.text_count(main_id));
        assert_eq!(names.len(), expected_count, "{target}");
        for role in [
            "CliffMurmursAboutDayHeLeftHometown",
            "AnnGreetsPlayerOnSnowyDay",
            "AnnRecognizesCollapsedCliff",
            "AnnCallsDougForHelp",
            "DoctorThanksPlayerForFindingCliffBeforeTooLate",
            "CarterRelievedCliffIsSafeAndAsksCause",
            "AnnThanksPlayerForSavingCliff",
            "DoctorSaysCliffNeedsRest",
        ] {
            let expected = format!("gText_NPCEvent_Cliff_CollapsesInSnow_{role}");
            assert!(
                names
                    .iter()
                    .any(|actual| actual.as_deref() == Some(expected.as_str())),
                "{target}: missing {expected}"
            );
        }
        assert_eq!(
            names.iter().any(|actual| actual.as_deref()
                == Some("gText_NPCEvent_Cliff_CollapsesInSnow_DoctorSpouseThanksPlayerByNicknameForFindingCliff")),
            target.contains("MFOMT"),
            "{target}"
        );
        let followup_id = 782 + shift;
        assert_eq!(
            symbols.script_name(followup_id),
            Some("EventScript_NPCEvent_Cliff_CollapsesInSnow_CliffPhoto_FollowupCliffDialogue"),
            "{target}"
        );
        let followup_names = symbols.names(followup_id, symbols.text_count(followup_id));
        assert_eq!(followup_names.len(), 4, "{target}");
        assert!(followup_names
            .iter()
            .flatten()
            .all(|name| name
                .starts_with("gText_NPCEvent_Cliff_CollapsesInSnow_CliffPhoto_Followup_")));
    }
    for stale in [
        "CollapsesInSnow_FollowupCliffDialogue",
        "CollapsesInSnow_IAlwaysRememberTheDayI",
        "CollapsesInSnow_ThankGoodnessYouHappenedByWhen",
    ] {
        assert!(
            !source.contains(stale),
            "stale Cliff collapse role: {stale}"
        );
    }
}

