#[test]
fn won_intro_apple_and_vase_events_use_sales_roles_and_region_topology() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, shift, jp) in [
        ("MARY_FOMT_US", 0, false),
        ("MARY_FOMT_JP", 0, true),
        ("MARY_MFOMT_US", 9, false),
        ("MARY_MFOMT_JP", 9, true),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let intro = symbols.names(810 + shift, 4);
        for role in [
            "WonGreetsPlayer",
            "WonIntroducesHimselfAsTravelingSalesman",
            "WonAdvertisesRareSeedsAtZacksHouse",
            "WonLeavesToContinueSalesRounds",
        ] {
            let expected = format!("gText_NPCEvent_Won_Introduction_{role}");
            assert!(
                intro.iter().any(|name| name.as_deref() == Some(&expected)),
                "{target}: {role}"
            );
        }
        let apples = symbols.names(811 + shift, symbols.text_count(811 + shift));
        assert_eq!(apples.len(), if jp { 18 } else { 20 }, "{target}");
        for role in [
            "WonOffersThreeRareApples",
            "WonIntroducesSUGDWApple",
            "WonIntroducesHMSGBApple",
            "WonIntroducesAEPFEApple",
            "WonOffersEachAppleFor500G",
            "AppleSelectionPrompt",
            "SelectSUGDWApple",
            "SelectHMSGBApple",
            "SelectAEPFEApple",
            "DeclineApplePurchase",
            "WonThanksPlayerForBuyingApple",
            "WonMocksPlayerForLacking500G",
        ] {
            let expected = format!("gText_NPCEvent_Won_AppleChallenge_{role}");
            assert!(
                apples.iter().any(|name| name.as_deref() == Some(&expected)),
                "{target}: {role}"
            );
        }
        assert_eq!(
            apples.iter().any(|name| name.as_deref()
                == Some("gText_NPCEvent_Won_AppleChallenge_WonStrugglesToRememberHMSGBName")),
            !jp,
            "{target}: US-only HMSGB aside"
        );
        assert_eq!(
            apples.iter().any(|name| name.as_deref()
                == Some("gText_NPCEvent_Won_AppleChallenge_WonPraisesAEPFEName")),
            !jp,
            "{target}: US-only AEPFE aside"
        );
        let vase = symbols.names(812 + shift, 7);
        for role in [
            "WonComplimentsFarmhouse",
            "WonOffersVaseFor5000G",
            "BuyVaseChoice",
            "DeclineVaseChoice",
            "WonClaimsVaseIsRareMingDynastyPiece",
            "WonSaysPlayerMustSupplyFlowers",
            "WonClaimsBeautyBenefitsSoul",
        ] {
            let expected = format!("gText_NPCEvent_Won_VasePurchase_{role}");
            assert!(
                vase.iter().any(|name| name.as_deref() == Some(&expected)),
                "{target}: {role}"
            );
        }
    }
    for stale in [
        "Introduction_ImWonByName",
        "AppleChallenge_IBrought3",
        "AppleChallenge_ThisIsTheFirstKindIts",
        "AppleChallenge_ThanksVeryMuchIDidntThink",
        "VasePurchase_ThisIsAVeryBeautifulHouse",
        "VasePurchase_WhatThisHouseLacksIsA",
    ] {
        assert!(!source.contains(stale), "stale Won sales name: {stale}");
    }
}

