#[test]
fn jewel_exchanges_are_collection_achievements_with_retry_semantics() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, shift) in [
        ("MARY_FOMT_US", 0),
        ("MARY_FOMT_JP", 0),
        ("MARY_MFOMT_US", 9),
        ("MARY_MFOMT_JP", 9),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        for (id, script, text) in [
            (
                816 + shift,
                "EventScript_AchievementEvent_Collection_HarvestGoddessJewelsExchange",
                "gText_AchievementEvent_Collection_HarvestGoddessJewelsExchange_GoddessExchangesJewelsForGoddessGem",
            ),
            (
                818 + shift,
                "EventScript_AchievementEvent_Collection_KappaJewelsExchange",
                "gText_AchievementEvent_Collection_KappaJewelsExchange_KappaExchangesJewelsForKappaGem",
            ),
        ] {
            assert_eq!(symbols.script_name(id), Some(script), "{target}: {id}");
            assert_eq!(symbols.names(id, 1)[0].as_deref(), Some(text), "{target}: {id}");
        }
        assert_eq!(
            symbols.names(817 + shift, 1)[0].as_deref(),
            Some("gText_NPCEvent_Kappa_DailyOfferingAppearance_KappaSilentlyAcceptsOffering"),
            "{target}: Kappa offering"
        );
        let truth_id = 820 + shift;
        assert_eq!(
            symbols.script_name(truth_id),
            Some("EventScript_AchievementEvent_Collection_JewelsOfTruthExchange"),
            "{target}: truth exchange"
        );
        for role in [
            "ThomasRecognizesFinalJewelAndLeadsPlayer",
            "ThomasOffersGemOfTruthExchange",
            "ThomasDefersExchangeUntilToolSlotAvailable",
        ] {
            let expected =
                format!("gText_AchievementEvent_Collection_JewelsOfTruthExchange_{role}");
            assert!(
                symbols
                    .names(truth_id, 3)
                    .iter()
                    .any(|name| name.as_deref() == Some(expected.as_str())),
                "{target}: {role}"
            );
        }
    }
    for stale in [
        "EventScript_SystemEvent_HarvestGoddessJewelsExchange",
        "EventScript_SystemEvent_KappaJewelsExchange",
        "EventScript_SystemEvent_JewelsOfTruthExchange",
        "DailyOfferingAppearance_SilentReaction",
    ] {
        assert!(!source.contains(stale), "stale jewel event name: {stale}");
    }
}

