#[test]
fn festival_calendar_names_and_year_end_windows_align_across_all_targets() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, script_id, has_early_winter) in [
        ("MARY_FOMT_US", 403, false),
        ("MARY_FOMT_JP", 403, true),
        ("MARY_MFOMT_US", 412, true),
        ("MARY_MFOMT_JP", 412, true),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        assert_eq!(
            symbols.script_name(script_id),
            Some("EventScript_SystemMenu_FestivalCalendar"),
            "{target} slot {script_id}"
        );
        let names = symbols.names(script_id, symbols.text_count(script_id));
        for expected in [
            "gText_SystemMenu_FestivalCalendar_YearEndEventsFallPreview",
            "gText_SystemMenu_FestivalCalendar_YearEndAndNewYearEventsLateWinter",
        ] {
            assert!(
                names
                    .iter()
                    .any(|actual| actual.as_deref() == Some(expected)),
                "{target} slot {script_id}: missing {expected}"
            );
        }
        assert_eq!(
            names.iter().any(|actual| {
                actual.as_deref()
                    == Some("gText_SystemMenu_FestivalCalendar_YearEndEventsEarlyWinter")
            }),
            has_early_winter,
            "{target} slot {script_id}: wrong early-winter calendar topology"
        );
    }
}

