#[test]
fn karen_duke_drinking_contest_uses_one_event_identity_and_speaker_roles() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, script_id, expected_count) in [
        ("MARY_FOMT_US", 763, 37),
        ("MARY_FOMT_JP", 763, 39),
        ("MARY_MFOMT_US", 772, 37),
        ("MARY_MFOMT_JP", 772, 39),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        assert_eq!(
            symbols.script_name(script_id),
            Some("EventScript_NPCEvent_KarenAndDuke_DrinkingContestAndDebtSettlement"),
            "{target}"
        );
        let names = symbols.names(script_id, symbols.text_count(script_id));
        assert_eq!(names.len(), expected_count, "{target}");
        for role in [
            "KarenExplainsDukesSupermarketDebtAndContest",
            "DukeExplainsWagerToSettleDebt",
            "KarenAsksPlayerToJudgeContest",
            "KarenDrunkenlyDeclaresVictory",
            "DougAsksPlayerToEscortDukeHome",
            "MannaSaysPlayerReportedDrinkingContest",
            "MannaRemindsDukeHeMustPayDebt",
            "MannaSaysDebtWillComeFromDukesAllowance",
            "DukeThanksAndApologizesToPlayer",
            "PlayerLeavesBeforeDukeAndMannasArgument",
        ] {
            let expected =
                format!("gText_NPCEvent_KarenAndDuke_DrinkingContestAndDebtSettlement_{role}");
            assert!(
                names
                    .iter()
                    .any(|actual| actual.as_deref() == Some(expected.as_str())),
                "{target}: missing {expected}"
            );
        }
    }

    for stale in [
        "EventScript_NPCEvent_KarenAndDuke_DrinkingContestChoice",
        "gText_NPCEvent_KarenAndDuke_DrinkingContest_HiPlayerYouveComeJustIn",
        "gText_NPCEvent_KarenAndDuke_DrinkingContestChoice_HiPlayerYouveComeJustIn",
    ] {
        assert!(
            !source.contains(stale),
            "stale Karen/Duke identity: {stale}"
        );
    }
}

