#[test]
fn harris_dialogue_roles_preserve_gamecube_report_and_cross_location_str_sharing() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, slot, expects_gamecube, separate_gotz_high) in [
        ("MARY_FOMT_US", 1023, false, true),
        ("MARY_FOMT_JP", 1023, false, false),
        ("MARY_MFOMT_US", 1093, true, false),
        ("MARY_MFOMT_JP", 1093, true, false),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let names = symbols.names(slot, symbols.text_count(slot));
        let has = |suffix: &str| {
            let expected = format!("gText_NPCEvent_Harris_DialogueAndGiftResponses_{suffix}");
            names.iter().any(|name| name.as_deref() == Some(&expected))
        };
        for role in [
            "Introduction",
            "BirthdayGiftResponse",
            "RecipeTeachingFriedRice",
            "CommentsOnBlueFeather",
            "OutdoorAfter18FirstConversation",
            "OutdoorBefore18NonSunnyRepeatConversation",
            "OutdoorBefore18SunnyFriendship0To100FirstConversation",
            "YodelRanchHouseRepeatConversation",
            "InnFirstConversation",
            "GotzHouseFriendship0To100RepeatConversation",
        ] {
            assert!(has(role), "{target} slot {slot}: missing {role}");
        }
        assert_eq!(has("GameCubeLinkMurreyReportPart1"), expects_gamecube);
        assert_eq!(has("GameCubeLinkMurreyReportPart2"), expects_gamecube);
        assert_eq!(
            has("GotzHouseFriendshipAbove100FirstConversation"),
            separate_gotz_high
        );
        assert_eq!(
            has("GotzHouseFriendshipAbove100RepeatConversation"),
            separate_gotz_high
        );
        assert_eq!(
            has("SharedOutdoorBefore18SunnyOrGotzHouseFriendshipAbove100FirstConversation"),
            !separate_gotz_high
        );
        assert_eq!(
            has("SharedOutdoorBefore18SunnyOrGotzHouseFriendshipAbove100RepeatConversation"),
            !separate_gotz_high
        );
        assert_eq!(
            has("SharedOutdoorAfter18OrGotzHouseFriendshipAbove100RepeatConversation"),
            slot == 1093
        );
        assert_eq!(has("OutdoorAfter18RepeatConversation"), slot == 1023);
        assert_eq!(
            has("OutdoorBefore18SunnyFriendshipAbove100FirstConversation"),
            separate_gotz_high
        );
    }
}

