#[test]
fn event_icon_callables_keep_their_target_ids() {
    for (target, create_id, remove_id) in [
        ("MARY_FOMT_US", 0x139, 0x13A),
        ("MARY_FOMT_JP", 0x139, 0x13A),
        ("MARY_MFOMT_US", 0x13D, 0x13E),
        ("MARY_MFOMT_JP", 0x13D, 0x13E),
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(
            &fs::read_to_string("goodies/mary_constants.mary.h").unwrap(),
            &options,
        )
        .unwrap();
        for (value, canonical, legacy) in [
            (0, "EVENT_ICON_LAYER_HIGHEST_PRIORITY", "EVENT_ICON_LAYER_0"),
            (1, "EVENT_ICON_LAYER_HIGH_PRIORITY", "EVENT_ICON_LAYER_1"),
            (2, "EVENT_ICON_LAYER_LOW_PRIORITY", "EVENT_ICON_LAYER_2"),
            (3, "EVENT_ICON_LAYER_LOWEST_PRIORITY", "EVENT_ICON_LAYER_3"),
        ] {
            assert_eq!(
                constants.const_int_value(canonical),
                Some(value),
                "{target}"
            );
            assert_eq!(constants.const_int_value(legacy), Some(value), "{target}");
        }
        let callables = parse_callable_table_with_scope(
            &fs::read_to_string("goodies/mary_callables.mary.h").unwrap(),
            &options,
            &constants,
        )
        .unwrap();
        let callable_map = callables.scope.callable_map();
        assert_eq!(callable_map["CreateEventIcon"].0 .0, create_id, "{target}");
        assert_eq!(callable_map["RemoveEventIcon"].0 .0, remove_id, "{target}");
        let icon_slot_type = constants.user_type("MaryEventIconSlot").unwrap();
        let map_x_type = constants.user_type("MaryMapSpaceX").unwrap();
        let map_y_type = constants.user_type("MaryMapSpaceY").unwrap();
        let icon_layer_type = constants.user_type("MaryEventIconLayer").unwrap();
        let icon_id_type = constants.user_type("MaryEventIconId").unwrap();
        assert_eq!(
            callable_map["CreateEventIcon"].1.parameter_types(),
            &[
                mary::ir::ValueType::UserType(icon_slot_type),
                mary::ir::ValueType::UserType(map_x_type),
                mary::ir::ValueType::UserType(map_y_type),
                mary::ir::ValueType::UserType(icon_layer_type),
                mary::ir::ValueType::UserType(icon_id_type),
            ],
            "{target}"
        );
        assert_eq!(
            callable_map["RemoveEventIcon"].1.parameter_types(),
            &[mary::ir::ValueType::UserType(icon_slot_type)],
            "{target}"
        );

        let script_table =
            parse_script_table("mary_script_table { TestEventIcon, };\n", &options).unwrap();
        for (layer, symbol) in [
            (0, Some("EVENT_ICON_LAYER_HIGHEST_PRIORITY")),
            (1, Some("EVENT_ICON_LAYER_HIGH_PRIORITY")),
            (2, Some("EVENT_ICON_LAYER_LOW_PRIORITY")),
            (3, Some("EVENT_ICON_LAYER_LOWEST_PRIORITY")),
            (4, None),
        ] {
            let numeric = parse_named_scripts(
                &format!("void TestEventIcon(void) {{ CreateEventIcon(0, 10, 20, {layer}, 0); }}"),
                &options,
                &callables.scope,
                &script_table,
            )
            .unwrap();
            let raised =
                decompile_script_named(&numeric.scripts[0].2, &callables.scope, "TestEventIcon")
                    .unwrap();
            let source = format_named_script("TestEventIcon", &raised).unwrap();
            if let Some(symbol) = symbol {
                assert!(source.contains(symbol), "{target}: {source}");
            } else {
                assert!(
                    source.contains("Y(20), 4,"),
                    "must not truncate bytecode to layer zero: {target}: {source}"
                );
            }
            let rebuilt =
                parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
            assert_eq!(
                encode_script(&numeric.scripts[0].2),
                encode_script(&rebuilt.scripts[0].2),
                "{target}: layer {layer}"
            );
        }
        let numeric = parse_named_scripts(
            "void TestEventIcon(void) { CreateEventIcon(0, 288, 123, 2, GetFoodIconId(FOOD_CAKE)); RemoveEventIcon(1); }\n",
            &options,
            &callables.scope,
            &script_table,
        )
        .unwrap();
        let raised =
            decompile_script_named(&numeric.scripts[0].2, &callables.scope, "TestEventIcon")
                .unwrap();
        let source = format_named_script("TestEventIcon", &raised).unwrap();
        assert!(
            source.contains("CreateEventIcon(EVENT_ICON_SLOT_0, X(288), Y(123), EVENT_ICON_LAYER_LOW_PRIORITY, GetFoodIconId(FOOD_CAKE))"),
            "{target}: {source}"
        );
        assert!(
            source.contains("RemoveEventIcon(EVENT_ICON_SLOT_1)"),
            "{target}: {source}"
        );
        let symbolic =
            parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
        assert_eq!(
            encode_script(&numeric.scripts[0].2),
            encode_script(&symbolic.scripts[0].2),
            "{target}"
        );

        let compound = parse_named_scripts(
            "void TestEventIcon(void) { CreateEventIcon(0, 20 * 8 + 8, 18 * 8 + 8 + 4, 2, GetFoodIconId(FOOD_CAKE)); }\n",
            &options,
            &callables.scope,
            &script_table,
        )
        .unwrap();
        let raised =
            decompile_script_named(&compound.scripts[0].2, &callables.scope, "TestEventIcon")
                .unwrap();
        let source = format_named_script("TestEventIcon", &raised).unwrap();
        assert!(
            source.contains("X(20 * 8 + 8), Y(18 * 8 + 8 + 4)"),
            "{target}: compound coordinates lost their domains: {source}"
        );
        let rebuilt =
            parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
        assert_eq!(
            encode_script(&compound.scripts[0].2),
            encode_script(&rebuilt.scripts[0].2),
            "{target}: compound coordinate identity wrappers changed bytecode"
        );

        let local_coordinate = parse_named_scripts(
            "void TestEventIcon(void) { int x; int y; x = 20 * 8 + 8; y = 18 * 8 + 8 + 4; CreateEventIcon(0, x, y, 2, GetFoodIconId(FOOD_CAKE)); }\n",
            &options,
            &callables.scope,
            &script_table,
        )
        .unwrap();
        let raised = decompile_script_named(
            &local_coordinate.scripts[0].2,
            &callables.scope,
            "TestEventIcon",
        )
        .unwrap();
        let source = format_named_script("TestEventIcon", &raised).unwrap();
        assert!(
            source.contains("CreateEventIcon(EVENT_ICON_SLOT_0, X(var_0), Y(var_1), EVENT_ICON_LAYER_LOW_PRIORITY, GetFoodIconId(FOOD_CAKE))"),
            "{target}: local coordinate uses lost their domains: {source}"
        );
        let rebuilt =
            parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
        assert_eq!(
            encode_script(&local_coordinate.scripts[0].2),
            encode_script(&rebuilt.scripts[0].2),
            "{target}: local coordinate identity wrappers changed bytecode"
        );

        let mut negative_coordinates = parse_named_scripts(
            "void TestEventIcon(void) { CreateEventIcon(0, -48, -32, 2, GetFoodIconId(FOOD_CAKE)); }\n",
            &options,
            &callables.scope,
            &script_table,
        )
        .unwrap();
        let raised = decompile_script_named(
            &negative_coordinates.scripts[0].2,
            &callables.scope,
            "TestEventIcon",
        )
        .unwrap();
        let source = format_named_script("TestEventIcon", &raised).unwrap();
        assert!(
            source.contains("X(-48), Y(-32)"),
            "{target}: direct negative coordinates lost their domains: {source}"
        );
        let rebuilt =
            parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
        assert_eq!(
            encode_script(&negative_coordinates.scripts[0].2),
            encode_script(&rebuilt.scripts[0].2),
            "{target}: direct negative coordinate wrappers changed bytecode"
        );

        let instructions = &mut negative_coordinates.scripts[0].2.instructions;
        let direct_x = instructions
            .iter()
            .position(|instruction| *instruction == Ins::PushInt(-48))
            .unwrap();
        instructions[direct_x] = Ins::PushInt(48);
        instructions.insert(direct_x + 1, Ins::Neg);
        let raised = decompile_script_named(
            &negative_coordinates.scripts[0].2,
            &callables.scope,
            "TestEventIcon",
        )
        .unwrap();
        let source = format_named_script("TestEventIcon", &raised).unwrap();
        assert!(
            source.contains("X(mary_negated_int(-48)), Y(-32)"),
            "{target}: positive-push-plus-Neg coordinate lost its physical form: {source}"
        );
        let rebuilt =
            parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
        assert_eq!(
            encode_script(&negative_coordinates.scripts[0].2),
            encode_script(&rebuilt.scripts[0].2),
            "{target}: negated coordinate wrappers changed bytecode"
        );
        for callable in ["GetFoodIconId", "GetArticleIconId", "GetToolIconId"] {
            assert_eq!(
                callable_map[callable].1.return_type(),
                mary::ir::ValueType::UserType(icon_id_type),
                "{target}: {callable}"
            );
        }

        let script_table =
            parse_script_table("mary_script_table { TestEventIcon, };\n", &options).unwrap();
        parse_named_scripts(
            "void TestEventIcon(void) {\n\
             CreateEventIcon(2, 176, 152, 1, GetFoodIconId(5));\n\
             RemoveEventIcon(2);\n\
             }\n",
            &options,
            &callables.scope,
            &script_table,
        )
        .unwrap();
    }
}

#[test]
fn map_local_door_indices_use_explicit_physical_slot_constants() {
    for target in [
        "MARY_FOMT_US",
        "MARY_FOMT_JP",
        "MARY_MFOMT_US",
        "MARY_MFOMT_JP",
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(
            &fs::read_to_string("goodies/mary_constants.mary.h").unwrap(),
            &options,
        )
        .unwrap();
        let callables = parse_callable_table_with_scope(
            &fs::read_to_string("goodies/mary_callables.mary.h").unwrap(),
            &options,
            &constants,
        )
        .unwrap();
        let door_type = constants.user_type("MaryDoorIndex").unwrap();
        for slot in 0..=13 {
            assert_eq!(
                constants.typed_int_const_name(door_type, slot),
                Some(format!("DOOR_SLOT_{slot}").as_str()),
                "{target}: local door slot {slot}"
            );
        }
        assert!(constants.typed_int_const_name(door_type, 14).is_none());
        for callable in ["OpenDoor", "CloseDoor"] {
            assert_eq!(
                callables.scope.callable_map()[callable].1.parameter_types(),
                &[mary::ir::ValueType::UserType(door_type)],
                "{target}: {callable}"
            );
        }

        let script_table =
            parse_script_table("mary_script_table { TestDoor, };\n", &options).unwrap();
        let numeric = parse_named_scripts(
            "void TestDoor(void) { OpenDoor(4); CloseDoor(4); }\n",
            &options,
            &callables.scope,
            &script_table,
        )
        .unwrap();
        let raised =
            decompile_script_named(&numeric.scripts[0].2, &callables.scope, "TestDoor").unwrap();
        let source = format_named_script("TestDoor", &raised).unwrap();
        assert!(
            source.contains("OpenDoor(DOOR_SLOT_4)"),
            "{target}: {source}"
        );
        assert!(
            source.contains("CloseDoor(DOOR_SLOT_4)"),
            "{target}: {source}"
        );
        let rebuilt =
            parse_named_scripts(&source, &options, &callables.scope, &script_table).unwrap();
        assert_eq!(
            encode_script(&numeric.scripts[0].2),
            encode_script(&rebuilt.scripts[0].2),
            "{target}"
        );
    }
}

