#[test]
fn chicken_family_slot_metadata_covers_every_shared_livestock_callable() {
    for target in [
        "MARY_FOMT_US",
        "MARY_FOMT_JP",
        "MARY_MFOMT_US",
        "MARY_MFOMT_JP",
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(
            &fs::read_to_string("goodies/mary_constants.mary.h").unwrap(),
            &options,
        )
        .unwrap();
        let chicken_slot_type = mary::ir::ValueType::UserType(
            constants
                .user_type("MaryChickenSlotIndex")
                .expect("missing chicken slot type"),
        );
        for (callable, discriminator_index, target_index) in [
            ("DoesAnimalExist", 0, 1),
            ("GetAnimalName", 1, 2),
            ("HasAnimalBeenTalkedTo", 0, 1),
            ("SetAnimalTalkedTo", 0, 1),
            ("AddAnimalAffection", 0, 1),
            ("IsAnimalUnhappy", 0, 1),
            ("IsAnimalSick", 0, 1),
            ("GetAnimalAge", 0, 1),
            ("GetAnimalAffection", 0, 1),
            ("GetAnimalGrowthStage", 0, 1),
            ("SetContestAnimal", 0, 1),
        ] {
            assert_eq!(
                constants.dependent_callable_parameter_type(
                    callable,
                    discriminator_index,
                    3,
                    target_index,
                ),
                Some(chicken_slot_type),
                "{target}: {callable}"
            );
        }
        assert_eq!(
            constants.dependent_callable_return_type("GetContestAnimalIndex", 0, 3),
            Some(chicken_slot_type),
            "{target}"
        );
        assert_eq!(
            constants.dependent_callable_return_type("SelectFestivalAnimal", 0, 0),
            Some(chicken_slot_type),
            "{target}"
        );
    }
}

#[test]
fn horse_and_dog_handlers_expose_their_ignored_index_argument() {
    let source = fs::read_to_string("goodies/mary_constants.mary.h").unwrap();
    for target in [
        "MARY_FOMT_US",
        "MARY_FOMT_JP",
        "MARY_MFOMT_US",
        "MARY_MFOMT_JP",
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(&source, &options).unwrap();
        let ignored_type = mary::ir::ValueType::UserType(
            constants.user_type("MaryIgnoredPetIndexArgument").unwrap(),
        );
        for callable in [
            "DoesAnimalExist",
            "GetAnimalName",
            "HasAnimalBeenTalkedTo",
            "SetAnimalTalkedTo",
            "AddAnimalAffection",
            "IsAnimalUnhappy",
            "IsAnimalSick",
            "IsAnimalPregnant",
            "GetAnimalHealthyPregnancyDays",
            "GetAnimalAge",
            "GetAnimalAffection",
            "GetAnimalGrowthStage",
        ] {
            for kind in [0, 4] {
                let (discriminator_index, target_index) = if callable == "GetAnimalName" {
                    (1, 2)
                } else {
                    (0, 1)
                };
                assert_eq!(
                    constants.dependent_callable_parameter_type(
                        callable,
                        discriminator_index,
                        kind,
                        target_index,
                    ),
                    Some(ignored_type),
                    "{target}: {callable}: pet kind {kind}"
                );
            }
        }

        for callable in ["IsAnimalPregnant", "GetAnimalHealthyPregnancyDays"] {
            assert_eq!(
                constants.dependent_callable_parameter_type(callable, 0, 3, 1),
                Some(mary::ir::ValueType::UserType(
                    constants.user_type("MaryChickenSlotIndex").unwrap(),
                )),
                "{target}: {callable}: chicken roster"
            );
        }
        let type_id = constants.user_type("MaryIgnoredPetIndexArgument").unwrap();
        assert_eq!(
            constants.typed_int_const_name(type_id, 0),
            Some("PET_INDEX_ARGUMENT_IGNORED_ZERO")
        );
        assert_eq!(
            constants.typed_int_const_name(type_id, 1),
            Some("PET_INDEX_ARGUMENT_IGNORED_ONE")
        );
        assert_eq!(constants.typed_int_const_name(type_id, 2), None);
    }
}

#[test]
fn caught_fish_state_callables_keep_their_target_ids() {
    for (target, name_id, size_id, maximum_id, king_id) in [
        ("MARY_FOMT_US", 0x11B, 0x11C, 0x11D, 0x11E),
        ("MARY_FOMT_JP", 0x11B, 0x11C, 0x11D, 0x11E),
        ("MARY_MFOMT_US", 0x11E, 0x11F, 0x120, 0x121),
        ("MARY_MFOMT_JP", 0x11E, 0x11F, 0x120, 0x121),
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(
            &fs::read_to_string("goodies/mary_constants.mary.h").unwrap(),
            &options,
        )
        .unwrap();
        let callables = parse_callable_table_with_scope(
            &fs::read_to_string("goodies/mary_callables.mary.h").unwrap(),
            &options,
            &constants,
        )
        .unwrap();
        let map = callables.scope.callable_map();
        assert_eq!(
            map["SetTextVariableToCaughtFishName"].0 .0, name_id,
            "{target}"
        );
        assert_eq!(map["GetCaughtFishSize"].0 .0, size_id, "{target}");
        assert_eq!(map["IsCaughtFishMaximumSize"].0 .0, maximum_id, "{target}");
        assert_eq!(map["IsCaughtFishKing"].0 .0, king_id, "{target}");
    }
}

