#[test]
fn script_local_purchase_and_blacksmith_domains_are_target_correct() {
    let header = fs::read_to_string("goodies/mary_constants.mary.h").unwrap();
    let symbols_source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, tv_slot, blacksmith_slot, mirror_slot) in [
        ("MARY_FOMT_US", 285, 487, None),
        ("MARY_FOMT_JP", 285, 487, None),
        ("MARY_MFOMT_US", 294, 496, Some(359)),
        ("MARY_MFOMT_JP", 294, 496, Some(359)),
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(&header, &options).unwrap();
        let symbols = parse_text_name_table(&symbols_source, &options).unwrap();

        let purchase_type = constants
            .constant_value_type("TV_SHOPPING_PHONE_ORDER_PURCHASED")
            .unwrap();
        let product_type = constants
            .constant_value_type("BLACKSMITH_PRODUCT_CATEGORY_TOOL")
            .unwrap();
        assert_eq!(
            symbols
                .local_types(tv_slot, &constants)
                .unwrap()
                .get("var_1"),
            Some(&purchase_type),
            "{target} TV Shopping outcome"
        );
        assert_eq!(
            symbols
                .local_types(blacksmith_slot, &constants)
                .unwrap()
                .get("var_0"),
            Some(&product_type),
            "{target} blacksmith product category"
        );
        if let Some(mirror_slot) = mirror_slot {
            assert_eq!(
                symbols
                    .local_types(mirror_slot, &constants)
                    .unwrap()
                    .get("var_6"),
                Some(&product_type),
                "{target} Shopping Master product category"
            );
        }
    }
}

#[test]
fn npc_held_item_interaction_locals_cover_the_complete_target_script_sets() {
    let header = fs::read_to_string("goodies/mary_constants.mary.h").unwrap();
    let symbols_source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, slot_count, expected_count) in [
        ("MARY_FOMT_US", 1329, 32),
        ("MARY_FOMT_JP", 1329, 32),
        ("MARY_MFOMT_US", 1416, 33),
        ("MARY_MFOMT_JP", 1416, 33),
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(&header, &options).unwrap();
        let symbols = parse_text_name_table(&symbols_source, &options).unwrap();
        let interaction_type = constants
            .constant_value_type("NPC_INTERACTION_SPECIAL_FAVORITE_GIFT")
            .unwrap();
        let typed_scripts = (0..slot_count)
            .filter(|&slot| {
                symbols.local_types(slot, &constants).unwrap().get("var_0")
                    == Some(&interaction_type)
            })
            .map(|slot| symbols.script_name(slot).unwrap().to_owned())
            .collect::<Vec<_>>();
        assert_eq!(typed_scripts.len(), expected_count, "{target}");
        for required in [
            "EventScript_NPCEvent_Ann_DialogueAndGiftResponses",
            "EventScript_NPCEvent_Cliff_DialogueAndGiftResponses",
            "EventScript_NPCEvent_Ellen_DialogueAndGiftResponses",
            "EventScript_NPCEvent_Baby_DialogueAndInteractions",
        ] {
            assert!(
                typed_scripts.iter().any(|name| name == required),
                "{target}: {required}"
            );
        }
        let anna_slot = (0..slot_count)
            .find(|slot| {
                symbols.script_name(*slot)
                    == Some("EventScript_NPCEvent_Anna_DialogueAndGiftResponses")
            })
            .unwrap();
        let anna_names = symbols.names(anna_slot, symbols.text_count(anna_slot));
        for suffix in [
            "FavoriteGiftResponse",
            "LikedGiftResponse",
            "NeutralGiftResponse",
            "DislikedGiftResponse",
            "HatedGiftResponse",
            "FavorableAnimalResponse",
            "UnfavorableAnimalResponse",
            "AccessoryGiftResponse",
            "CosmeticGiftResponse",
            "PerfumeGiftResponse",
        ] {
            let expected = format!("gText_NPCEvent_Anna_DialogueAndGiftResponses_{suffix}");
            assert!(
                anna_names
                    .iter()
                    .any(|actual| actual.as_deref() == Some(&expected)),
                "{target}: missing {expected}"
            );
        }
        for suffix in [
            "Introduction",
            "BirthdayGiftAcknowledgement",
            "CommentsOnBlueFeather",
            "BasilHouse1FLowFriendshipFirstConversation",
            "BasilHouse1FLowFriendshipRepeatConversation",
            "BasilHouse1FHighFriendshipFirstConversation",
            "BasilHouse1FHighFriendshipRepeatConversation",
            "BasilHouse2FSunnyFirstConversation",
            "BasilHouse2FSunnyRepeatConversation",
            "BasilHouse2FRainyFirstConversation",
            "BasilHouse2FRainyRepeatConversationPart1",
            "BasilHouse2FRainyRepeatConversationPart2",
            "NorthSideTownEveningConversation",
            "NorthSideTownNonMondayDaytimeConversation",
            "NorthSideTownMondayDaytimeConversation",
            "SupermarketLowFriendshipFirstConversation",
            "SupermarketLowFriendshipRepeatConversation",
            "SupermarketHighFriendshipFirstConversation",
            "SupermarketHighFriendshipRepeatConversation",
            "RoseSquareFirstConversation",
            "RoseSquareRepeatConversation",
            "MothersHillMiddleLowFriendshipFirstConversation",
            "MothersHillMiddleLowFriendshipRepeatConversation",
            "MothersHillMiddleHighFriendshipFirstConversation",
            "MothersHillMiddleHighFriendshipRepeatConversation",
        ] {
            let expected = format!("gText_NPCEvent_Anna_DialogueAndGiftResponses_{suffix}");
            assert!(
                anna_names
                    .iter()
                    .any(|actual| actual.as_deref() == Some(&expected)),
                "{target}: missing {expected}"
            );
        }
        for suffix in [
            "MaryChildBornBasilHouse1FFirstConversation",
            "MaryChildBornBasilHouse1FRepeatConversation",
        ] {
            let expected = format!("gText_NPCEvent_Anna_DialogueAndGiftResponses_{suffix}");
            assert_eq!(
                anna_names
                    .iter()
                    .any(|actual| actual.as_deref() == Some(&expected)),
                target.contains("FOMT_") && !target.contains("MFOMT"),
                "{target}: incorrect FoMT-only Anna childbirth role visibility for {expected}"
            );
        }
        assert_eq!(
            typed_scripts
                .iter()
                .any(|name| name == "EventScript_NPCEvent_Van_DialogueAndGiftResponses"),
            target.contains("MFOMT"),
            "{target}: Van is MFoMT-only"
        );
        assert_eq!(
            typed_scripts.iter().any(|name| {
                name == "EventScript_NPCEvent_LouOrRuby_DailyDialogueAndCookingRecipes"
            }),
            target.contains("FOMT_") && !target.contains("MFOMT"),
            "{target}: the separate Lou-or-Ruby daily script is FoMT-only"
        );
    }

    for required in [
        "gText_NPCEvent_Baby_DialogueAndInteractions_InfantMediumFriendshipRepeatOrYoungChildLikedGiftOrFavorableAnimalResponse",
        "gText_NPCEvent_Baby_DialogueAndInteractions_YoungChildHatedGiftOrUnfavorableAnimalResponse",
        "gText_NPCEvent_Baby_DialogueAndInteractions_YoungChildAccessoryOrCosmeticGiftResponse",
        "gText_NPCEvent_Gourmet_DialogueAndGiftResponses_NonFoodPresentationResponse",
        "gText_NPCEvent_Gray_DialogueAndGiftResponses_NonPlayerSpouseCosmeticOrPerfumeGiftResponse",
        "gText_NPCEvent_Won_DialogueAndGiftResponses_NonPlayerSpouseAccessoryOrCosmeticGiftResponse",
    ] {
        assert!(symbols_source.contains(required), "missing {required}");
    }
}

