#[test]
fn semantic_state_variables_do_not_fall_back_to_numeric_values() {
    const SEMANTIC_SUFFIXES: [&str; 9] = [
        "STATE",
        "RESULT",
        "STATUS",
        "PHASE",
        "TYPE",
        "KIND",
        "MODE",
        "CHOICE",
        "SELECTION",
    ];

    fn starts_with_integer(source: &str) -> bool {
        let source = source.trim_start();
        let source = source.strip_prefix('-').unwrap_or(source);
        source.as_bytes().first().is_some_and(u8::is_ascii_digit)
    }

    for directory in [
        "decompiled_text/fomt_us",
        "decompiled_text/fomt_jp",
        "decompiled_text/mfomt_us",
        "decompiled_text/mfomt_jp",
    ] {
        if !std::path::Path::new(directory).is_dir() {
            continue;
        }

        for entry in fs::read_dir(directory).unwrap().filter_map(Result::ok) {
            if entry
                .path()
                .extension()
                .is_none_or(|extension| extension != "c")
            {
                continue;
            }
            let source = fs::read_to_string(entry.path()).unwrap();
            for line in source.lines() {
                for call in ["VarGet(VAR_", "VarSet(VAR_"] {
                    let mut remainder = line;
                    while let Some(start) = remainder.find(call) {
                        remainder = &remainder[start + call.len()..];
                        let Some(name_end) = remainder.find(|character: char| {
                            !character.is_ascii_alphanumeric() && character != '_'
                        }) else {
                            break;
                        };
                        let name = &remainder[..name_end];
                        remainder = &remainder[name_end..];
                        if !SEMANTIC_SUFFIXES
                            .iter()
                            .any(|suffix| name.ends_with(suffix))
                        {
                            continue;
                        }

                        let numeric_value = if call.starts_with("VarGet") {
                            remainder
                                .strip_prefix(')')
                                .map(str::trim_start)
                                .and_then(|tail| {
                                    ["==", "!=", "<=", ">=", "<", ">"]
                                        .into_iter()
                                        .find_map(|operator| tail.strip_prefix(operator))
                                })
                                .is_some_and(starts_with_integer)
                        } else {
                            remainder.strip_prefix(',').is_some_and(starts_with_integer)
                        };
                        assert!(
                            !numeric_value,
                            "{directory}: {} lost the symbolic value domain for VAR_{name}: {line}",
                            entry.file_name().to_string_lossy()
                        );
                    }
                }
            }
        }
    }
}

#[test]
fn vanilla_outputs_do_not_compare_typed_callable_returns_with_known_numeric_members() {
    fn parse_integer_prefix(source: &str) -> Option<i64> {
        let source = source.trim_start();
        let (negative, source) = source
            .strip_prefix('-')
            .map_or((false, source), |source| (true, source));
        let (radix, digits) = source
            .strip_prefix("0x")
            .or_else(|| source.strip_prefix("0X"))
            .map_or((10, source), |source| (16, source));
        let length = digits
            .bytes()
            .take_while(|byte| match radix {
                16 => byte.is_ascii_hexdigit(),
                _ => byte.is_ascii_digit(),
            })
            .count();
        if length == 0 {
            return None;
        }
        let value = i64::from_str_radix(&digits[..length], radix).ok()?;
        Some(if negative { -value } else { value })
    }

    fn matching_parenthesis(source: &str, open: usize) -> Option<usize> {
        let mut depth = 0usize;
        let mut string = false;
        let mut escaped = false;
        for (offset, byte) in source.as_bytes()[open..].iter().copied().enumerate() {
            if string {
                if escaped {
                    escaped = false;
                } else if byte == b'\\' {
                    escaped = true;
                } else if byte == b'"' {
                    string = false;
                }
                continue;
            }
            match byte {
                b'"' => string = true,
                b'(' => depth += 1,
                b')' => {
                    depth = depth.checked_sub(1)?;
                    if depth == 0 {
                        return Some(open + offset);
                    }
                }
                _ => {}
            }
        }
        None
    }

    let constants_source = include_str!("../goodies/mary_constants.mary.h");
    let callables_source = include_str!("../goodies/mary_callables.mary.h");
    for (target, directory) in [
        ("MARY_FOMT_US", "decompiled_text/fomt_us"),
        ("MARY_FOMT_JP", "decompiled_text/fomt_jp"),
        ("MARY_MFOMT_US", "decompiled_text/mfomt_us"),
        ("MARY_MFOMT_JP", "decompiled_text/mfomt_jp"),
    ] {
        if !std::path::Path::new(directory).is_dir() {
            continue;
        }
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(constants_source, &options).unwrap();
        let callables =
            parse_callable_table_with_scope(callables_source, &options, &constants).unwrap();

        for entry in fs::read_dir(directory).unwrap().filter_map(Result::ok) {
            if entry
                .path()
                .extension()
                .is_none_or(|extension| extension != "c")
            {
                continue;
            }
            let source = fs::read_to_string(entry.path()).unwrap();
            for (line_number, line) in source.lines().enumerate() {
                for (name, (_, shape)) in callables.scope.callable_map() {
                    let mary::ir::ValueType::UserType(type_id) = shape.return_type() else {
                        continue;
                    };
                    let needle = format!("{name}(");
                    let mut search_start = 0usize;
                    while let Some(relative_open) = line[search_start..].find(&needle) {
                        let open = search_start + relative_open + name.len();
                        let Some(close) = matching_parenthesis(line, open) else {
                            break;
                        };
                        let tail = line[close + 1..].trim_start();
                        let numeric = ["==", "!=", "<=", ">=", "<", ">"]
                            .into_iter()
                            .find_map(|operator| tail.strip_prefix(operator))
                            .and_then(parse_integer_prefix);
                        if let Some(value) = numeric {
                            assert!(
                                constants.typed_int_const_name(type_id, value).is_none(),
                                "{target}: {}:{} compares {name}'s typed return with known numeric member {value}: {line}",
                                entry.file_name().to_string_lossy(),
                                line_number + 1
                            );
                        }
                        search_start = close + 1;
                    }
                }
            }

            let mut local_return_types = HashMap::<String, Option<usize>>::new();
            for line in source.lines() {
                let line = line.trim();
                let Some((local, value)) = line.split_once(" = ") else {
                    continue;
                };
                if !local.starts_with("var_")
                    || !local
                        .bytes()
                        .all(|byte| byte.is_ascii_alphanumeric() || byte == b'_')
                {
                    continue;
                }
                let callable = value
                    .split_once('(')
                    .filter(|(_, arguments)| {
                        matching_parenthesis(value, value.len() - arguments.len() - 1).is_some()
                    })
                    .map(|(name, _)| name.trim());
                let assigned_type = callable
                    .and_then(|name| callables.scope.callable_map().get(name))
                    .and_then(|(_, shape)| match shape.return_type() {
                        mary::ir::ValueType::UserType(type_id) => Some(type_id),
                        _ => None,
                    });
                local_return_types
                    .entry(local.to_owned())
                    .and_modify(|current| {
                        if *current != assigned_type {
                            *current = None;
                        }
                    })
                    .or_insert(assigned_type);
            }

            for (local, type_id) in local_return_types {
                let Some(type_id) = type_id else {
                    continue;
                };
                let needle = format!("switch ({local})");
                let mut remainder = source.as_str();
                while let Some(switch_start) = remainder.find(&needle) {
                    remainder = &remainder[switch_start + needle.len()..];
                    let Some(open) = remainder.find('{') else {
                        break;
                    };
                    let mut depth = 1usize;
                    for line in remainder[open + 1..].lines() {
                        if depth == 1 {
                            if let Some(case) = line.trim().strip_prefix("case ") {
                                if let Some(value) = parse_integer_prefix(case) {
                                    assert!(
                                        constants.typed_int_const_name(type_id, value).is_none(),
                                        "{target}: {} switches on {local}'s typed callable return with known numeric member {value}: {line}",
                                        entry.file_name().to_string_lossy()
                                    );
                                }
                            }
                        }
                        for byte in line.bytes() {
                            match byte {
                                b'{' => depth += 1,
                                b'}' => depth = depth.saturating_sub(1),
                                _ => {}
                            }
                        }
                        if depth == 0 {
                            break;
                        }
                    }
                }
            }
        }
    }
}

#[test]
fn early_farm_event_text_symbols_follow_their_full_event_identity() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let cases = [
        (5usize, "EventScript_FarmEvent_Foal_OfferToPlayer"),
        (6, "EventScript_FarmEvent_Horse_CareEvaluation"),
        (7, "EventScript_FarmEvent_Foal_MoveIntoStable"),
        (8, "EventScript_FarmEvent_Cow_InteractionStatus"),
        (13, "EventScript_FarmEvent_Sheep_InteractionStatus"),
    ];

    for target in [
        "MARY_FOMT_US",
        "MARY_FOMT_JP",
        "MARY_MFOMT_US",
        "MARY_MFOMT_JP",
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        for (script_id, script_name) in cases {
            assert_eq!(
                symbols.script_name(script_id),
                Some(script_name),
                "{target}"
            );
            let text_prefix = format!("gText_{}", &script_name["EventScript_".len()..]);
            let names = symbols.names(script_id, symbols.text_count(script_id));
            assert!(!names.is_empty(), "{target}: slot {script_id}");
            assert!(
                names.iter().flatten().all(
                    |name| name == &text_prefix || name.starts_with(&format!("{text_prefix}_"))
                ),
                "{target}: slot {script_id} text identity diverges from {script_name}: {names:?}"
            );
        }
    }
}

#[test]
