#[test]
fn mfomt_interleaved_unknowns_are_not_conflated_with_thanksgiving_bachelor_flags() {
    let generated_sources = ["decompiled_text/mfomt_us", "decompiled_text/mfomt_jp"]
        .iter()
        .filter(|path| std::path::Path::new(path).is_dir())
        .flat_map(|path| {
            fs::read_dir(path)
                .unwrap()
                .filter_map(Result::ok)
                .filter(|entry| entry.path().extension().is_some_and(|ext| ext == "c"))
                .map(|entry| fs::read_to_string(entry.path()).unwrap())
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>();
    for target in ["MARY_MFOMT_US", "MARY_MFOMT_JP"] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(
            &fs::read_to_string("goodies/mary_constants.mary.h").unwrap(),
            &options,
        )
        .unwrap();
        let variable_type = constants.user_type("MaryVarId").unwrap();

        for id in [482, 484, 486, 488, 490] {
            let unknown_name = format!("VAR_UNKNOWN_SLOT_{id:03}");
            assert_eq!(
                constants.typed_int_const_name(variable_type, id),
                Some(unknown_name.as_str()),
                "{target}: an interleaved unknown was assigned from adjacency alone"
            );
            assert!(
                generated_sources
                    .iter()
                    .all(|source| !source.contains(&unknown_name)),
                "{target}: update the zero-reference audit before changing slot {id}"
            );
        }
        for (id, character) in [
            (493, "KAI"),
            (494, "CLIFF"),
            (495, "DOCTOR"),
            (496, "RICK"),
            (497, "GRAY"),
            (498, "WON"),
            (499, "GOURMET"),
        ] {
            let expected = format!("VAR_WINTER_THANKSGIVING_GIFT_GIVEN_TO_{character}");
            assert_eq!(
                constants.typed_int_const_name(variable_type, id),
                Some(expected.as_str()),
                "{target}: verified bachelor Thanksgiving flag"
            );
        }
    }
}

#[test]
fn every_physical_callable_has_a_semantic_name_for_every_target() {
    let header = fs::read_to_string("goodies/mary_constants.mary.h").unwrap();
    let callables_source = fs::read_to_string("goodies/mary_callables.mary.h").unwrap();

    let generic_parameters = callables_source
        .split(|ch: char| !(ch.is_ascii_alphanumeric() || ch == '_'))
        .filter(|token| {
            token.strip_prefix("arg_").is_some_and(|suffix| {
                !suffix.is_empty() && suffix.chars().all(|ch| ch.is_ascii_digit())
            })
        })
        .collect::<Vec<_>>();
    assert!(
        generic_parameters.is_empty(),
        "generic callable parameter placeholders remain: {generic_parameters:?}"
    );

    for target in [
        "MARY_FOMT_US",
        "MARY_FOMT_JP",
        "MARY_MFOMT_US",
        "MARY_MFOMT_JP",
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(&header, &options).unwrap();
        let callables =
            parse_callable_table_with_scope(&callables_source, &options, &constants).unwrap();

        let numbered = callables
            .scope
            .callable_map()
            .keys()
            .filter(|name| {
                ["Func", "Proc"].iter().any(|prefix| {
                    name.strip_prefix(prefix).is_some_and(|suffix| {
                        !suffix.is_empty() && suffix.chars().all(|ch| ch.is_ascii_hexdigit())
                    })
                })
            })
            .cloned()
            .collect::<Vec<_>>();

        assert!(
            numbered.is_empty(),
            "{target}: numbered callable placeholders remain: {numbered:?}"
        );
    }
}

#[test]
fn harvest_goddess_link_meter_and_mfomt_countdown_symbols_keep_their_physical_roles() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let prefix = "gText_NPCEvent_HarvestGoddess_OfferingsAndMatchmakingChoices_";

    for (target, script_id, has_countdown) in [
        ("MARY_FOMT_US", 571, false),
        ("MARY_FOMT_JP", 571, false),
        ("MARY_MFOMT_US", 580, true),
        ("MARY_MFOMT_JP", 580, true),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let names = symbols.names(script_id, symbols.text_count(script_id));
        let present = names
            .iter()
            .flatten()
            .map(String::as_str)
            .collect::<Vec<_>>();

        for filled_stars in 0..=42 {
            let expected = format!("{prefix}LinkStrengthMeter_{filled_stars:02}FilledStars");
            assert!(
                present.contains(&expected.as_str()),
                "{target} slot {script_id}: missing {expected}"
            );
        }
        assert_eq!(
            present
                .iter()
                .filter(|name| name.starts_with(&format!("{prefix}LinkStrengthMeter_")))
                .count(),
            43,
            "{target} slot {script_id}: link meter must cover exactly 0..=42 filled stars"
        );

        for remaining in 1..=9 {
            let expected = format!("{prefix}SpecialOfferingRewardCountdown_{remaining}");
            assert_eq!(
                present.contains(&expected.as_str()),
                has_countdown,
                "{target} slot {script_id}: incorrect countdown visibility for {expected}"
            );
        }
        assert!(
            present
                .iter()
                .all(|name| !name.starts_with(&format!("{prefix}NonverbalReaction"))),
            "{target} slot {script_id}: data display strings regressed to a dialogue fallback name"
        );

        for role in [
            "FirstOfferingOnGoddessBirthdayGreeting",
            "FirstRegularOfferingGreeting",
            "RepeatOfferingOnGoddessBirthdayGreeting",
            "RepeatRegularOfferingGreeting",
            "TenOfferingsPowerBerryReward",
            "TenOfferingsMatchmakingWishOffer",
            "LaterTenOfferingWhiteGrassReward",
        ] {
            assert!(
                present.contains(&format!("{prefix}{role}").as_str()),
                "{target} slot {script_id}: missing {role}"
            );
        }
        for role in ["ChoiceHasRomanticInterest", "ChoiceHasNoRomanticInterest"] {
            assert_eq!(
                present.contains(&format!("{prefix}{role}").as_str()),
                target.ends_with("_JP"),
                "{target} slot {script_id}: incorrect JP-specific {role} visibility"
            );
        }
        assert_eq!(
            present.contains(&format!("{prefix}WhiteGrassRewardFarewell").as_str()),
            target.ends_with("_JP"),
            "{target} slot {script_id}: incorrect JP white-grass farewell visibility"
        );
        assert_eq!(
            present
                .contains(&format!("{prefix}KaiAlreadyMarriedAlternativeRewardFarewell").as_str()),
            target == "MARY_MFOMT_US",
            "{target} slot {script_id}: incorrect MFoMT-US Kai fallback visibility"
        );
    }

    for stale in [
        "WellIfItIsntPlayerHow_02",
        "WellIfItIsntPlayerYouve_02",
        "SinceYouveComeAndVisitedMe_02",
        "SinceYouveComeAndVisitedMe_03",
        "OfferingsAndMatchmakingChoices_Yes_02",
        "OfferingsAndMatchmakingChoices_No_02",
        "ComeAgainAnyTime_02",
        "ComeBackAnyTimeAfterMatchmakingReward",
    ] {
        assert!(
            !source.contains(stale),
            "stale Harvest Goddess name: {stale}"
        );
    }
}

