#[test]
fn timid_low_friendship_repeat_silences_preserve_the_regional_slot_difference() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let shared =
        "gText_NPCEvent_Timid_DialogueAndWorkChoices_LowFriendshipRepeatConversationSilentPause";
    let us_only = "gText_NPCEvent_Timid_DialogueAndWorkChoices_NonSpringLowFriendshipRepeatConversationLongSilentPause";

    for (target, script_id, expects_us_only_slot) in [
        ("MARY_FOMT_US", 1000, true),
        ("MARY_FOMT_JP", 1000, false),
        ("MARY_MFOMT_US", 1069, true),
        ("MARY_MFOMT_JP", 1069, false),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let names = symbols.names(script_id, symbols.text_count(script_id));
        let present = names
            .iter()
            .flatten()
            .map(String::as_str)
            .collect::<Vec<_>>();

        assert!(
            present.contains(&shared),
            "{target}: missing shared silence"
        );
        for suffix in [
            "SpringFriendship000To050FirstConversationAnticipatesTeaParty",
            "SpringFriendship051To100FirstConversationExplainsTeaPartyWithFriends",
            "SpringFriendship101To150FirstConversationAsksIfPlayerAnticipatesTeaParty",
            "SpringFriendship151PlusFirstConversationHappyPlayerWillAttendTeaParty",
            "SpringFriendship051To100RepeatConversationLikesSpringAndTeaParty",
            "SpringFriendship101To150RepeatConversationEnjoysTalkingWithFriendsAtTeaParty",
            "SpringFriendship151PlusRepeatConversationInvitesPlayerAfterSpring",
            "NonSpringFriendship000To050FirstConversationExplainsShyness",
            "NonSpringFriendship051To100FirstConversationWelcomesPlayer",
            "NonSpringFriendship101To150FirstConversationAsksPlayerNotToBullyHim",
            "NonSpringFriendship151PlusFirstConversationOffersPlayerAFavor",
            "NonSpringFriendship051To100RepeatConversationTiredFromWork",
            "NonSpringFriendship101To150RepeatConversationTrustsPlayer",
            "NonSpringFriendship151PlusRepeatConversationPraisesPlayersKindness",
        ] {
            let expected = format!("gText_NPCEvent_Timid_DialogueAndWorkChoices_{suffix}");
            assert!(
                present.contains(&expected.as_str()),
                "{target}: missing structured dialogue symbol {expected}"
            );
        }
        assert_eq!(
            present.contains(&us_only),
            expects_us_only_slot,
            "{target}: incorrect visibility for the US-only longer non-spring silence"
        );
        assert!(
            present.iter().all(|name| {
                !name.ends_with("DialogueAndWorkChoices_SilentPause")
                    && !name.ends_with("DialogueAndWorkChoices_SilentPause_02")
            }),
            "{target}: generic or mechanically suffixed Timid silence remains"
        );
    }
}

