#[test]
fn pedometer_and_shipping_milestones_preserve_complete_order_and_ring_difference() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let pedometer_steps = [
        "10000",
        "100000",
        "1000000",
        "10000000",
        "100000000",
        "1000000000",
    ];
    let shipping_counts = [
        "10000",
        "100000",
        "1000000",
        "10000000",
        "100000000",
        "1000000000",
    ];
    for (target, first_pedometer, first_shipping, mfomt) in [
        ("MARY_FOMT_US", 822, 828, false),
        ("MARY_FOMT_JP", 822, 828, false),
        ("MARY_MFOMT_US", 831, 837, true),
        ("MARY_MFOMT_JP", 831, 837, true),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        for (offset, steps) in pedometer_steps.iter().enumerate() {
            let suffix = if mfomt && *steps == "10000000" {
                format!("Pedometer_{steps}StepsRingReward")
            } else {
                format!("Pedometer_{steps}Steps")
            };
            let slot = first_pedometer + offset;
            assert_eq!(
                symbols.script_name(slot),
                Some(format!("EventScript_AchievementEvent_{suffix}").as_str()),
                "{target}: pedometer slot {slot}"
            );
            assert_eq!(
                symbols.text_count(slot),
                if mfomt && *steps == "10000000" { 2 } else { 1 },
                "{target}: pedometer text topology at {slot}"
            );
        }
        for (offset, count) in shipping_counts.iter().enumerate() {
            let slot = first_shipping + offset;
            let suffix = format!("Shipping_{count}Items");
            assert_eq!(
                symbols.script_name(slot),
                Some(format!("EventScript_AchievementEvent_{suffix}").as_str()),
                "{target}: shipping slot {slot}"
            );
            assert_eq!(
                symbols.text_count(slot),
                1,
                "{target}: shipping slot {slot}"
            );
        }
        let every_kind_slot = first_shipping + shipping_counts.len();
        assert_eq!(
            symbols.script_name(every_kind_slot),
            Some("EventScript_AchievementEvent_Shipping_EveryItemKind"),
            "{target}: every-kind shipping slot"
        );
    }
}

#[test]
fn mine_achievement_sequence_and_adjacent_empty_slots_stay_physical() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let achievements = [
        "SpringMine_ReachedB100",
        "SpringMine_ReachedB200",
        "SpringMine_ReachedBottom",
        "SpringMine_CollectedEveryItem",
        "LakeMine_CollectedEveryItem",
    ];
    for (target, first_empty, first_achievement) in [
        ("MARY_FOMT_US", 835, 842),
        ("MARY_FOMT_JP", 835, 842),
        ("MARY_MFOMT_US", 844, 851),
        ("MARY_MFOMT_JP", 844, 851),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        for slot in first_empty..first_empty + 7 {
            assert_eq!(
                symbols.script_name(slot),
                Some(format!("EventScript_{slot:04}").as_str()),
                "{target}: empty physical slot {slot}"
            );
            assert_eq!(symbols.text_count(slot), 0, "{target}: empty slot {slot}");
        }
        for (offset, suffix) in achievements.iter().enumerate() {
            let slot = first_achievement + offset;
            let expected = format!("EventScript_AchievementEvent_{suffix}");
            assert_eq!(
                symbols.script_name(slot),
                Some(expected.as_str()),
                "{target}: mine achievement slot {slot}"
            );
            assert_eq!(symbols.text_count(slot), 1, "{target}: mine slot {slot}");
            assert_eq!(
                symbols.names(slot, 1)[0].as_deref(),
                Some(format!("gText_AchievementEvent_{suffix}").as_str()),
                "{target}: mine achievement text {slot}"
            );
        }
    }
}

#[test]
fn hidden_candidate_proposals_preserve_gender_split_and_dialogue_roles() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for target in ["MARY_FOMT_US", "MARY_FOMT_JP"] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        assert_eq!(
            symbols.script_name(847),
            Some("EventScript_LoveEvent_HarvestGoddess_ProposalResponse"),
            "{target}: Harvest Goddess proposal slot"
        );
        assert_eq!(
            symbols.names(847, 2),
            vec![
                Some("gText_LoveEvent_HarvestGoddess_ProposalResponse_AcceptsProposal".into()),
                Some("gText_LoveEvent_HarvestGoddess_ProposalResponse_RejectsProposalWhenRequirementsUnmet".into()),
            ],
            "{target}: Harvest Goddess proposal roles"
        );
    }
    for target in ["MARY_MFOMT_US", "MARY_MFOMT_JP"] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        for (slot, candidate, roles) in [
            (
                856,
                "Gourmet",
                vec![
                    "ApprovesFarmhouseAsProposalLocation",
                    "AcceptsProposal",
                    "ReturnsToWorkAfterAcceptingProposal",
                ],
            ),
            (
                857,
                "Kappa",
                vec![
                    "AcceptsProposalAndTellsPlayerNotToReturn",
                    "RejectsProposalWhenRequirementsUnmet",
                ],
            ),
            (
                858,
                "Won",
                vec![
                    "ApprovesFarmhouseAsProposalLocation",
                    "AcceptsProposal",
                    "ReturnsToWorkAfterAcceptingProposal",
                ],
            ),
        ] {
            assert_eq!(
                symbols.script_name(slot),
                Some(format!("EventScript_LoveEvent_{candidate}_Proposal").as_str()),
                "{target}: {candidate} proposal slot"
            );
            for (actual, role) in symbols.names(slot, roles.len()).iter().zip(roles) {
                assert_eq!(
                    actual.as_deref(),
                    Some(format!("gText_LoveEvent_{candidate}_Proposal_{role}").as_str()),
                    "{target}: {candidate}: {role}"
                );
            }
        }
    }
    for stale in [
        "ProposalResponse_Nope",
        "Proposal_OkayIllMarryYouDontCome",
        "Proposal_DismissesPlayer",
        "Proposal_ChoosesProposalLocation",
        "Proposal_SureIfYouWantMeTo",
        "Proposal_ReturnsToWork,",
    ] {
        assert!(!source.contains(stale), "stale proposal text name: {stale}");
    }
}

