#[test]
fn zack_empty_shipping_bin_advice_has_a_complete_typed_eight_value_cycle() {
    let source = fs::read_to_string("goodies/mary_constants.mary.h").unwrap();
    assert!(source.contains(
        "mary_var_type(VAR_ZACK_EMPTY_SHIPPING_BIN_ADVICE_CYCLE, MaryZackEmptyShippingBinAdvice);"
    ));
    let expected = [
        "ZACK_EMPTY_SHIPPING_BIN_ADVICE_RAISE_CHICKENS_FOR_EGGS",
        "ZACK_EMPTY_SHIPPING_BIN_ADVICE_RAISE_COWS_FOR_MILK",
        "ZACK_EMPTY_SHIPPING_BIN_ADVICE_RAISE_SHEEP_FOR_WOOL",
        "ZACK_EMPTY_SHIPPING_BIN_ADVICE_MINE_ORE",
        "ZACK_EMPTY_SHIPPING_BIN_ADVICE_WINTER_LAKE_MINE_GEMS",
        "ZACK_EMPTY_SHIPPING_BIN_ADVICE_FORAGE_MOUNTAINS_AND_FORESTS",
        "ZACK_EMPTY_SHIPPING_BIN_ADVICE_GROW_CROPS",
        "ZACK_EMPTY_SHIPPING_BIN_ADVICE_CATCH_FISH",
    ];
    for target in [
        "MARY_FOMT_US",
        "MARY_FOMT_JP",
        "MARY_MFOMT_US",
        "MARY_MFOMT_JP",
    ] {
        let options = Options::default().define(target).unwrap();
        let constants = parse_constant_header(&source, &options).unwrap();
        let advice_type = constants
            .user_type("MaryZackEmptyShippingBinAdvice")
            .unwrap();
        for (value, name) in expected.into_iter().enumerate() {
            assert_eq!(
                constants.typed_int_const_name(advice_type, value as i64),
                Some(name),
                "{target}: advice value {value}"
            );
        }
        assert!(
            constants.typed_int_const_name(advice_type, 8).is_none(),
            "{target}: advice domain must stop before value 8"
        );
    }
}

