#[test]
fn popuri_fomt_poultry_farm_spouse_names_preserve_region_specific_text_reuse() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let prefix = "gText_NPCEvent_Popuri_DialogueAndGiftResponses_";
    let shared_first = format!("{prefix}PlayerSpouseBelowGreenHeartFirstConversationAngrySilence");
    let common_tail = [
        "PlayerSpousePoultryFarmBelowGreenHeartRepeatConversation",
        "PlayerSpousePoultryFarmGreenHeartFirstConversation",
        "PlayerSpousePoultryFarmGreenHeartRepeatConversation",
        "PlayerSpousePoultryFarmYellowHeartFirstConversation",
        "PlayerSpousePoultryFarmYellowHeartRepeatConversation",
        "PlayerSpousePoultryFarmOrangeHeartFirstConversation",
        "PlayerSpousePoultryFarmOrangeHeartRepeatConversation",
        "PlayerSpousePoultryFarmRedHeartFirstConversation",
        "PlayerSpousePoultryFarmRedHeartRepeatConversation",
    ]
    .map(|role| format!("{prefix}{role}"));

    for target in ["MARY_FOMT_US", "MARY_FOMT_JP"] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let names = symbols
            .names(993, symbols.text_count(993))
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        if target == "MARY_FOMT_US" {
            let mut expected = vec![format!(
                "{prefix}PlayerSpousePoultryFarmBelowGreenHeartFirstConversation"
            )];
            expected.extend(common_tail.iter().cloned());
            assert!(
                names
                    .windows(expected.len())
                    .any(|window| window == expected),
                "{target}: poultry-farm spouse roles must preserve the US physical text sequence"
            );
        } else {
            assert!(
                names.contains(&shared_first),
                "{target}: the poultry-farm below-green first branch must reuse the shared angry-silence text"
            );
            assert!(
                names
                    .windows(common_tail.len())
                    .any(|window| window == common_tail),
                "{target}: the remaining poultry-farm spouse roles must preserve the JP physical text sequence"
            );
        }
    }

    for role in [
        "PlayerSpouseVisitsPoultryFarmDuringPregnancyFirstConversation",
        "PlayerSpouseVisitsPoultryFarmDuringPregnancyRepeatConversation",
        "PlayerSpouseVisitsPoultryFarmAfterChildbirthFirstConversation",
        "PlayerSpouseVisitsPoultryFarmAfterChildbirthRepeatConversation",
    ] {
        assert!(source.contains(&format!("{prefix}{role}")));
    }
}

