#[test]
fn festival_entrance_announcements_use_event_roles_on_all_targets() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    let festivals = [
        "NewYearsFestivalAnnouncement",
        "SpringHorseRaceAnnouncement",
        "CookingFestivalThemeAnnouncement",
        "ChickenFestivalAnnouncement",
        "CowFestivalAnnouncement",
        "HarvestFestivalAnnouncement",
        "FallHorseRaceAnnouncement",
        "SheepFestivalAnnouncement",
        "YearEndFestivalAnnouncement",
    ];
    for (target, first_script_id) in [
        ("MARY_FOMT_US", 689),
        ("MARY_FOMT_JP", 689),
        ("MARY_MFOMT_US", 698),
        ("MARY_MFOMT_JP", 698),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        for (offset, entrance) in [
            (0, "NorthTownEntrance"),
            (1, "SouthTownEntrance"),
            (2, "BeachEntrance"),
        ] {
            let script_id = first_script_id + offset;
            let event_name = format!("FestivalEvent_DayAnnouncement_{entrance}");
            let script_name = format!("EventScript_{event_name}");
            assert_eq!(
                symbols.script_name(script_id),
                Some(script_name.as_str()),
                "{target} slot {script_id}"
            );
            let prefix = format!("gText_{event_name}_");
            let expected = festivals
                .iter()
                .map(|festival| Some(format!("{prefix}{festival}")))
                .collect::<Vec<_>>();
            assert_eq!(
                symbols.names(script_id, symbols.text_count(script_id)),
                expected,
                "{target} slot {script_id}"
            );
        }
    }

    for target in ["MARY_FOMT_US", "MARY_FOMT_JP"] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        for (script_id, script_name, expected) in [
            (
                692,
                "EventScript_FestivalEvent_BeachDay_DayAnnouncement_WestEntrance",
                "gText_FestivalEvent_BeachDay_DayAnnouncement_WestEntrance_ThomasAnnouncesStartTimeAndInvitesPlayer",
            ),
            (
                693,
                "EventScript_FestivalEvent_BeachDay_DayAnnouncement_SouthEntrance",
                "gText_FestivalEvent_BeachDay_DayAnnouncement_SouthEntrance_ThomasAnnouncesStartTimeAndInvitesPlayer",
            ),
        ] {
            assert_eq!(
                symbols.script_name(script_id),
                Some(script_name),
                "{target} slot {script_id}"
            );
            assert_eq!(
                symbols.names(script_id, symbols.text_count(script_id)),
                vec![Some(expected.to_owned())],
                "{target} slot {script_id}"
            );
        }
        assert_eq!(
            symbols.names(694, symbols.text_count(694)),
            vec![
                Some("gText_NPCEvent_Doctor_PlayerCollapseRecovery_DoctorExplainsPlayerCollapsedFromFatigue".to_owned()),
                Some("gText_NPCEvent_Doctor_PlayerCollapseRecovery_DoctorAdvisesPacingWorkAndOrdersRest".to_owned()),
            ],
            "{target} slot 694"
        );
    }
}

