#[test]
fn high_similarity_dialogue_scripts_keep_verified_mfomt_insertions() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, gotz_id, may_id, thomas_id, mary_gray_id, jeff_id, doctor_id, is_mfomt) in [
        ("MARY_FOMT_US", 1028, 1029, 738, 926, 769, 767, false),
        ("MARY_FOMT_JP", 1028, 1029, 738, 926, 769, 767, false),
        ("MARY_MFOMT_US", 1098, 1099, 747, 994, 778, 776, true),
        ("MARY_MFOMT_JP", 1098, 1099, 747, 994, 778, 776, true),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        for (script_id, expected, expected_visibility) in [
            (
                gotz_id,
                "gText_NPCEvent_Gotz_DialogueAndGiftResponses_ThanksgivingGiftResponse",
                is_mfomt,
            ),
            (
                may_id,
                "gText_NPCEvent_May_DialogueAndGiftResponses_GameCubeLinkMovingTeddyBearRumor",
                is_mfomt,
            ),
            (
                thomas_id,
                "gText_NPCEvent_Thomas_RandomItemRequestChoice_ThomasRemembersPlayerIsBusy",
                is_mfomt,
            ),
            (
                mary_gray_id,
                "gText_RivalEvent_MaryAndGray_01_BlackHeart_BlacksmithHandInjury_SaibaraLocalizationErrorClaimsGraysInjuryIsHisOwnFault",
                target == "MARY_MFOMT_US",
            ),
            (
                jeff_id,
                "gText_NPCEvent_Jeff_BloodTypeCorrection_DoctorGreetsSpouseByNickname",
                is_mfomt,
            ),
            (
                doctor_id,
                "gText_NPCEvent_Doctor_ReflectsOnParentsAndMedicalCalling_DoctorApologizesForTalkingAndStaysBehind",
                is_mfomt,
            ),
        ] {
            let names = symbols.names(script_id, symbols.text_count(script_id));
            assert_eq!(
                names.iter().any(|name| name.as_deref() == Some(expected)),
                expected_visibility,
                "{target} slot {script_id}: incorrect visibility for {expected}"
            );
        }
    }
}

#[test]
fn family_specific_equal_count_scripts_keep_real_semantic_differences() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, beach_exit_id, beach_dispatch_id, sasha_id, is_mfomt) in [
        ("MARY_FOMT_US", 107, 106, 1009, false),
        ("MARY_FOMT_JP", 107, 106, 1009, false),
        ("MARY_MFOMT_US", 115, 114, 1079, true),
        ("MARY_MFOMT_JP", 115, 114, 1079, true),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let exit_names = symbols
            .names(beach_exit_id, symbols.text_count(beach_exit_id))
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        let dispatch_names = symbols
            .names(beach_dispatch_id, symbols.text_count(beach_dispatch_id))
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        let festival = if is_mfomt {
            "FrisbeeTournament"
        } else {
            "BeachDayFestival"
        };
        assert!(
            exit_names.iter().any(|name| name.contains(festival)),
            "{target}: exit guard must retain the target's physical festival domain"
        );
        assert!(
            dispatch_names.iter().any(|name| name.contains(festival)),
            "{target}: beach dispatch must retain the target's physical festival domain"
        );

        let sasha_names = symbols
            .names(sasha_id, symbols.text_count(sasha_id))
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        let expected_sasha_roles = if is_mfomt {
            [
                "GameCubeLinkForgetMeNotValleyHughTrackRecordDialoguePart1",
                "GameCubeLinkForgetMeNotValleyHughTrackRecordDialoguePart2",
            ]
        } else {
            [
                "KarenChildBornFirstConversation",
                "KarenChildBornRepeatConversation",
            ]
        };
        for role in expected_sasha_roles {
            let expected = format!("gText_NPCEvent_Sasha_DialogueAndGiftResponses_{role}");
            assert!(
                sasha_names.iter().any(|name| name == &expected),
                "{target}: missing {expected}"
            );
        }
    }
}

#[test]
fn harvest_sprite_work_dialogue_preserves_family_specific_insertions() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, is_mfomt, is_us) in [
        ("MARY_FOMT_US", false, true),
        ("MARY_FOMT_JP", false, false),
        ("MARY_MFOMT_US", true, true),
        ("MARY_MFOMT_JP", true, false),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let sprite_slots = if is_mfomt {
            [
                (1068, "Staid"),
                (1069, "Timid"),
                (1070, "Nappy"),
                (1071, "Bold"),
                (1072, "Chef"),
                (1073, "Aqua"),
                (1074, "Hoggy"),
            ]
        } else {
            [
                (999, "Staid"),
                (1000, "Timid"),
                (1001, "Nappy"),
                (1002, "Bold"),
                (1003, "Chef"),
                (1004, "Aqua"),
                (1005, "Hoggy"),
            ]
        };
        for (script_id, sprite) in sprite_slots {
            let names = symbols
                .names(script_id, symbols.text_count(script_id))
                .into_iter()
                .flatten()
                .collect::<Vec<_>>();
            let has_role = |role: &str| {
                let expected = format!("gText_NPCEvent_{sprite}_DialogueAndWorkChoices_{role}");
                names.iter().any(|name| name == &expected)
            };
            assert_eq!(
                has_role("NoRequestOrExitTaskSelectionChoice"),
                is_mfomt && is_us,
                "{target}: {sprite} merged no-request choice"
            );
            assert_eq!(
                has_role("HarvestDurationPrompt"),
                !is_mfomt,
                "{target}: {sprite} FoMT harvest-only duration prompt"
            );
            assert_eq!(
                has_role("HarvestOrAnimalCareDurationPrompt"),
                is_mfomt,
                "{target}: {sprite} MFoMT shared duration prompt"
            );
            for role in [
                "AllMinigamesWinImprovement",
                if sprite == "Aqua" {
                    "WateringOrHarvestingMinigameLossConcern"
                } else {
                    "AllMinigamesLossConcern"
                },
            ] {
                assert_eq!(
                    has_role(role),
                    !is_mfomt && is_us,
                    "{target}: {sprite} FoMT shared minigame result {role}"
                );
            }
        }

        let timid_id = if is_mfomt { 1069 } else { 1000 };
        let timid_names = symbols
            .names(timid_id, symbols.text_count(timid_id))
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        let timid_no_request = "gText_NPCEvent_Timid_DialogueAndWorkChoices_NoRequestResponse";
        assert_eq!(
            timid_names.iter().any(|name| name == timid_no_request),
            is_mfomt && is_us,
            "{target}: Timid MFoMT-only separate no-request response"
        );
    }
}

#[test]
fn life_on_the_farm_preserves_mfomt_only_program_headers() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (region, fomt_target, mfomt_target) in [
        ("US", "MARY_FOMT_US", "MARY_MFOMT_US"),
        ("JP", "MARY_FOMT_JP", "MARY_MFOMT_JP"),
    ] {
        let fomt_options = Options::default().define(fomt_target).unwrap();
        let mfomt_options = Options::default().define(mfomt_target).unwrap();
        let fomt = parse_text_name_table(&source, &fomt_options).unwrap();
        let mfomt = parse_text_name_table(&source, &mfomt_options).unwrap();
        for (level, fomt_id, mfomt_id, mfomt_header) in [
            (
                "Advanced",
                1043,
                1114,
                [
                    "gText_TV_LifeOnTheFarm_Advanced_ProgramTitle",
                    "gText_TV_LifeOnTheFarm_Advanced_LevelTitle",
                    "gText_TV_LifeOnTheFarm_Advanced_OpeningBigSisterGreeting",
                    "gText_TV_LifeOnTheFarm_Advanced_LayoutPadding",
                ],
            ),
            (
                "Beginner",
                1044,
                1115,
                [
                    "gText_TV_LifeOnTheFarm_Beginner_LevelTitle",
                    "gText_TV_LifeOnTheFarm_Beginner_ProgramTitle",
                    "gText_TV_LifeOnTheFarm_Beginner_OpeningBigBrotherGreeting",
                    "gText_TV_LifeOnTheFarm_Beginner_LayoutPadding",
                ],
            ),
        ] {
            assert_eq!(
                fomt.script_name(fomt_id),
                mfomt.script_name(mfomt_id),
                "{region}: Life on the Farm {level} script role"
            );
            let fomt_names = fomt
                .names(fomt_id, fomt.text_count(fomt_id))
                .into_iter()
                .flatten()
                .collect::<Vec<_>>();
            let mfomt_names = mfomt
                .names(mfomt_id, mfomt.text_count(mfomt_id))
                .into_iter()
                .flatten()
                .collect::<Vec<_>>();
            assert_eq!(fomt_names.len(), 120, "{region}: {level} daily lessons");
            assert_eq!(
                mfomt_names.len(),
                124,
                "{region}: {level} header plus lessons"
            );
            assert_eq!(
                &mfomt_names[..4],
                mfomt_header,
                "{region}: MFoMT {level} physical header"
            );
            assert_eq!(
                fomt_names,
                mfomt_names[4..],
                "{region}: {level} four seasons of daily lessons"
            );
        }
    }
}

#[test]
fn mfomt_tv_program_headers_and_f314_us_preview_slots_keep_physical_scope() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, is_mfomt, is_us) in [
        ("MARY_FOMT_US", false, true),
        ("MARY_FOMT_JP", false, false),
        ("MARY_MFOMT_US", true, true),
        ("MARY_MFOMT_JP", true, false),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        for (slot, header_roles) in if is_mfomt {
            [
                (
                    1113,
                    [
                        "ProgramTitle",
                        "FairyAndMeTitle",
                        "ToBeContinuedCaption",
                        "LayoutPadding",
                    ],
                ),
                (
                    1117,
                    [
                        "ProgramTitle",
                        "AutumnTitle",
                        "BreezeTitle",
                        "LayoutPadding",
                    ],
                ),
            ]
        } else {
            [
                (
                    1042,
                    [
                        "ProgramTitle",
                        "FairyAndMeTitle",
                        "ToBeContinuedCaption",
                        "LayoutPadding",
                    ],
                ),
                (
                    1046,
                    [
                        "ProgramTitle",
                        "AutumnTitle",
                        "BreezeTitle",
                        "LayoutPadding",
                    ],
                ),
            ]
        } {
            let names = symbols
                .names(slot, symbols.text_count(slot))
                .into_iter()
                .flatten()
                .collect::<Vec<_>>();
            for role in header_roles {
                assert_eq!(
                    names.iter().any(|name| name.ends_with(&format!("_{role}"))),
                    is_mfomt,
                    "{target} slot {slot}: MFoMT-only program header {role}"
                );
            }
        }

        let f314_slot = if is_mfomt { 1110 } else { 1039 };
        let f314_names = symbols
            .names(f314_slot, symbols.text_count(f314_slot))
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        for role in ["Race12_PreviewPart02", "Race30_PreviewPart02"] {
            let expected = format!("gText_TV_F314MGrandPrix_{role}");
            assert_eq!(
                f314_names.iter().any(|name| name == &expected),
                is_mfomt && is_us,
                "{target} slot {f314_slot}: corrected US preview slot {role}"
            );
        }
    }
}

#[test]
fn entertainment_channel_weather_forecast_preserves_snowstorm_text_reuse() {
    let source = fs::read_to_string("goodies/mary_scripts_text.mary.sym").unwrap();
    for (target, slot, split_snowstorm_texts) in [
        ("MARY_FOMT_US", 1058, false),
        ("MARY_FOMT_JP", 1058, false),
        ("MARY_MFOMT_US", 1129, true),
        ("MARY_MFOMT_JP", 1129, false),
    ] {
        let options = Options::default().define(target).unwrap();
        let symbols = parse_text_name_table(&source, &options).unwrap();
        let names = symbols
            .names(slot, symbols.text_count(slot))
            .into_iter()
            .flatten()
            .collect::<Vec<_>>();
        let has = |role: &str| {
            let expected = format!("gText_TV_EntertainmentChannelWeatherForecast_{role}");
            names.iter().any(|name| name == &expected)
        };
        assert_eq!(
            has("FallToWinterSnowstorm"),
            split_snowstorm_texts,
            "{target}: dedicated fall-to-winter snowstorm text"
        );
        assert_eq!(
            has("WinterSnowstorm"),
            split_snowstorm_texts,
            "{target}: dedicated winter snowstorm text"
        );
        assert_eq!(
            has("FallToWinterOrWinterSnowstorm"),
            !split_snowstorm_texts,
            "{target}: physically shared snowstorm text"
        );
        assert!(
            !has("WinterSnowstormSevere"),
            "{target}: text wording does not prove a separate severity"
        );
    }
}

